window.POEM_DB=window.POEM_DB||{};POEM_DB["wj_000"]={"n":"无名氏","dyn":"魏晋","poems":[{"t":"无题","f":"五言绝句","c":["吴王好剑客，百姓多疮瘢。","楚王好细腰，宫中多饿死。"]},{"t":"古诗五首 其五","f":"五言古诗","c":["兰若生春阳，涉冬犹盛滋。","愿言追昔爱，情款感四时。","美人在云端，天路隔无期。","夜光照玄阴，长叹念所思。","谁谓我无忧，积念发狂痴。"]},{"t":"古乐府","f":"五言绝句","c":["兰草自然香，生于大道旁。","要镰八九月，俱在束薪中。"]},{"t":"古诗十九首 其十七","f":"五言古诗","c":["孟冬寒气至，北风何惨栗。","愁多知夜长，仰观众星列。","三五明月满，四五蟾兔缺。","客从远方来，遗我一书札。","上言长相思，下言久离别。","置书怀袖中，三岁字不灭。","一心抱区区，惧君不识察。"]},{"t":"古诗十九首 其十一","f":"五言古诗","c":["回车驾言迈，悠悠涉长道。","四顾何茫茫，东风摇百草。","所遇无故物，焉得不速老。","盛衰各有时，立身苦不早。","人生非金石，岂能长寿考。","奄忽随物化，荣名以为宝。"]},{"t":"古诗十九首 其十三","f":"五言古诗","c":["驱车上东门，遥望郭北墓。","白杨何萧萧，松柏夹广路。","下有陈死人，杳杳即长暮。","潜寐黄泉下，千载永不寤。","浩浩阴阳移，年命如朝露。","人生忽如寄，寿无金石固。","万岁更相送，贤圣莫能度。","服食求神仙，多为药所误。","不如饮美酒，被服纨与素。"]},{"t":"古诗十九首 其八","f":"五言古诗","c":["冉冉孤生竹，结根泰山阿。","与君为新婚，兔丝附女萝。","兔丝生有时，夫妇会有宜。","千里远结婚，悠悠隔山陂。","思君令人老，轩车来何迟。","伤彼蕙兰花，含英扬光辉。","过时而不采，将随秋草萎。","君亮执高节，贱妾亦何为。"]},{"t":"古诗十九首 其七","f":"五言古诗","c":["明月皎夜光，促织鸣东壁。","玉衡指孟冬，众星何历历。","白露沾野草，时节忽复易。","秋蝉鸣树间，玄鸟逝安适。","昔我同门友，高举振六翮。","不念携手好，弃我如遗迹。","南箕北有斗，牵牛不负轭。","良无盘石固，虚名复何益。"]},{"t":"古诗十九首 其六","f":"五言律诗","c":["涉江采芙蓉，兰泽多芳草。","采之欲遗谁，所思在远道。","还顾望旧乡，长路漫浩浩。","同心而离居，忧伤以终老。"]},{"t":"古诗十九首 其十二","f":"五言古诗","c":["东城高且长，逶迤自相属。","回风动地起，秋草萋已绿。","四时更变化，岁暮一何速。","晨风怀苦心，蟋蟀伤局促。","荡涤放情志，何为自结束。","燕赵多佳人，美者颜如玉。","被服罗裳衣，当户理清曲。","音响一何悲，弦急知柱促。","驰情整巾带，沉吟聊踯躅。","思为双飞燕，衔泥巢君屋。"]},{"t":"古诗十九首 其三","f":"五言古诗","c":["青青陵上柏，磊磊涧中石。","人生天地间，忽如远行客。","斗酒相娱乐，聊厚不为薄。","驱车策驽马，游戏宛与洛。","洛中何郁郁，冠带自相索。","长衢罗夹巷，王侯多第宅。","两宫遥相望，双阙百馀尺。","极宴娱心意，戚戚何所迫。"]},{"t":"古诗十九首 其四","f":"五言古诗","c":["今日良宴会，欢乐难具陈。","弹筝奋逸响，新声妙入神。","令德唱高言，识曲听其真。","齐心同所愿，含意俱未伸。","人生寄一世，奄忽若飙尘。","何不策高足，先据要路津。","无为守贫贱，轗轲长苦辛。"]},{"t":"古诗十九首 其十","f":"五言古诗","c":["迢迢牵牛星，皎皎河汉女。","纤纤擢素手，札札弄机杼。","终日不成章，泣涕零如雨。","河汉清且浅，相去复几许。","盈盈一水间，脉脉不得语。"]},{"t":"古诗十九首 其十四","f":"五言古诗","c":["去者日以疏，来者日以亲。","出郭门直视，但见丘与坟。","古墓犁为田，松柏摧为薪。","白杨多悲风，萧萧愁杀人。","思还故里闾，欲归道无因。"]},{"t":"古诗十九首 其五","f":"五言古诗","c":["西北有高楼，上与浮云齐。","交疏结绮窗，阿阁三重阶。","上有弦歌声，音响一何悲。","谁能为此曲，无乃杞梁妻。","清商随风发，中曲正徘徊。","一弹再三叹，慷慨有馀哀。","不惜歌者苦，但伤知音稀。","愿为双鸿鹄，奋翅起高飞。"]},{"t":"古诗十九首 其十八","f":"五言古诗","c":["客从远方来，遗我一端绮。","相去万馀里，故人心尚尔。","文彩双鸳鸯，裁为合欢被。","著以长相思，缘以结不解。","以胶投漆中，谁能别离此。"]},{"t":"古诗十九首 其九","f":"五言律诗","c":["庭中有奇树，绿叶发华滋。","攀条折其荣，将以遗所思。","馨香盈怀袖，路远莫致之。","此物何足贵，但感别经时。"]},{"t":"古诗十九首 其十五","f":"五言古诗","c":["生年不满百，常怀千岁忧。","昼短苦夜长，何不秉烛游。","为乐当及时，何能待来兹。","愚者爱惜费，但为后世嗤。","仙人王子乔，难可与等期。"]},{"t":"古诗十九首 其十六","f":"五言古诗","c":["凛凛岁云暮，蝼蛄夕鸣悲。","凉风率已厉，游子寒无衣。","锦衾遗洛浦，同袍与我违。","独宿累长夜，梦想见容辉。","良人惟古欢，枉驾惠前绥。","愿得常巧笑，携手同车归。","既来不须臾，又不处重闱。","亮无晨风翼，焉能凌风飞。","眄睐以适意，引领遥相睎。","徙倚怀感伤，垂涕沾双扉。"]},{"t":"古诗十九首 其十九","f":"五言古诗","c":["明月何皎皎，照我罗床帏。","忧愁不能寐，揽衣起徘徊。","客行虽云乐，不如早旋归。","出户独彷徨，愁思当告谁。","引领还入房，泪下沾裳衣。"]},{"t":"古诗十九首 其二","f":"五言古诗","c":["青青河畔草，郁郁园中柳。","盈盈楼上女，皎皎当窗牖。","娥娥红粉妆，纤纤出素手。","昔为倡家女，今为荡子妇。","荡子行不归，空床难独守。"]},{"t":"古绝句四首 其四","f":"五言绝句","c":["南山一桂树，上有双鸳鸯。","千年长交颈，欢爱不相忘。"]},{"t":"古绝句四首 其二","f":"五言绝句","c":["日暮秋云阴，江水清且深。","何用通音信，莲花玳瑁簪。"]},{"t":"古绝句四首 其一","f":"五言绝句","c":["藁砧今何在，山上复有山。","何当大刀头，破镜飞上天。"]},{"t":"古绝句四首 其三","f":"五言绝句","c":["菟丝从长风，根茎无断绝。","无情尚不离，有情安可别。"]},{"t":"古越谣歌","f":"古风","c":["君乘车，我戴笠，他日相逢下车揖。","君担簦，我跨马，他日相逢为君下。"]},{"t":"古诗五首 其二","f":"五言古诗","c":["四坐且莫喧，愿听歌一言。","请说铜炉器，崔嵬象南山。","上枝似松柏，下根据铜盘。","雕文各异类，离娄自相联。","谁能为此器，公输与鲁班。","朱火然其中，青烟飏其间。","从风入君怀，四坐莫不叹。","香风难久居，空令蕙草残。"]},{"t":"李陵录别诗二十一首 其四","f":"五言古诗","c":["骨肉缘枝叶，结交亦相因。","四海皆兄弟，谁为行路人。","况我连枝树，与子同一身。","昔为鸳与鸯，今为参与辰。","昔者常相近，邈若胡与秦。","惟念当乖离，恩情日以新。","鹿鸣思野草，可以喻嘉宾。","我有一尊酒，欲以赠远人。","愿子留斟酌，慰此平生亲。"]},{"t":"李陵录别诗二十一首 其一","f":"五言古诗","c":["良时不再至，离别在须臾。","屏营衢路侧，执手野踟蹰。","仰视浮云驰，奄忽互相逾。","风波一失所，各在天一隅。","长当从此别，且复立斯须。","欲因晨风发，送子以贱驱。"]},{"t":"李陵录别诗二十一首 其八","f":"五言古诗","c":["有鸟西南飞，熠熠似苍鹰。","朝发天北隅，暮闻日南陵。","欲寄一言去，托之笺彩缯。","因风附轻翼，以遗心蕴蒸。","鸟辞路悠长，羽翼不能胜。","意欲从鸟逝，驽马不可乘。"]},{"t":"古诗","f":"五言律诗","c":["步出城东门，遥望江南路。","前日风雪中，故人从此去。","我欲渡河水，河水深无梁。","愿为双黄鹄，高飞还故乡。"]},{"t":"刺巴郡郡守诗","f":"五言古诗","c":["狗吠何喧喧，有吏来在门。","披衣出门应，府记欲得钱。","语穷乞请期，吏怒反见尤。","旋步顾家中，家中无可为。","思往从邻贷，邻人言已匮。","钱钱何难得，令我独憔悴。"]},{"t":"时人为贡举语","f":"古风","c":["举秀才。","不知书。","举孝廉。","父别居。","寒素清白浊如泥。","高第良将怯如黾。"]},{"t":"顺帝末京都童谣","f":"古风","c":["直如弦，死道边。","曲如钩，反封侯。"]},{"t":"古诗三首 其三","f":"五言古诗","c":["新树兰蕙葩，杂用杜蘅草。","终朝采其华，日暮不盈抱。","采之欲遗谁，所思在远道。","馨香易销歇，繁华会枯槁。","怅望欲何言，临风送怀抱。"]},{"t":"古诗三首 其一","f":"五言古诗","c":["橘柚垂华实，乃在深山侧。","闻君好我甘，窃独自雕饰。","委身玉盘中，历年冀见食。","芳菲不相投，青黄忽改色。","人傥欲我知，因君为羽翼。"]},{"t":"古诗五首 其四","f":"五言律诗","c":["穆穆清风至，吹我罗衣裾。","青袍似春草，长条随风舒。","朝登津梁山，褰裳望所思。","安得抱柱信，皎日以为期。"]},{"t":"古诗五首 其一","f":"五言古诗","c":["上山采蘼芜，下山逢故夫。","长跪问故夫，新人复何如。","新人虽言好，未若故人姝。","颜色类相似，手爪不相如。","新人从门入，故人从阁去。","新人工织缣，故人工织素。","织缣日一匹，织素五丈馀。","将缣来比素，新人不如故。"]},{"t":"李陵录别诗二十一首 其二十","f":"五言古诗","c":["岩岩钟山首，赫赫炎天路。","高明曜云门，远景灼寒素。","昂昂累世士，结根在所固。","吕望老匹夫，苟为因世故。","管仲小囚臣，独能建功祚。","人生有何常，但恐年岁暮。","幸托不肖躯，且当猛虎步。","安能苦一身，与世同举厝。","由不慎小节，庸夫笑我度。","吕望尚不希，夷齐何足慕。"]},{"t":"李陵录别诗二十一首 其二十一","f":"五言古诗","c":["远送新行客，戚暮乃来归。","入门望爱子，妻妾向人悲。","闻子不可见，日已潜光辉。","孤坟在西北，常念君来迟。","褰裳上墟丘，但见蒿与薇。","白骨归黄泉，肌体乘尘飞。","生时不识父，死后知我谁。","孤魂游穷暮，飘遥安所依。","人生图嗣息，尔死我念追。","俯仰内伤心，不觉泪沾衣。","人生自有命，但恨生日希。"]},{"t":"孙皓初童谣","f":"五言绝句","c":["宁饮建业水，不食武昌鱼。","宁还建业死，不止武昌居。"]},{"t":"绵州巴歌","f":"古风","c":["豆子山，打瓦鼓。","扬平山，撒白雨。","下白雨，取龙女。","织得绢，二丈五。","一半属罗江，一半属玄武。"]},{"t":"子夜歌四十二首 其三十六","f":"五言绝句","c":["侬作北辰星，千年无转移。","欢行白日心，朝东暮还西。"]},{"t":"子夜歌四十二首 其七","f":"五言绝句","c":["始欲识郎时，两心望如一。","理丝入残机，何悟不成匹。"]},{"t":"懊侬歌十四首 其三","f":"五言绝句","c":["江陵去扬州，三千三百里。","已行一千三，所有二千在。"]},{"t":"子夜四时歌 春歌二十首 其十","f":"五言绝句","c":["春林花多媚，春鸟意多哀。","春风复多情，吹我罗裳开。"]},{"t":"子夜四时歌 春歌二十首 其一","f":"五言绝句","c":["春风动春心，流目瞩山林。","山林多奇采，阳鸟吐清音。"]},{"t":"子夜四时歌 春歌二十首 其二十","f":"五言绝句","c":["自从别欢后，叹音不绝响。","黄檗向春生，苦心随日长。"]},{"t":"子夜歌四十二首 其十一","f":"五言绝句","c":["高山种芙蓉，复经黄檗坞。","果得一莲时，流离婴辛苦。"]},{"t":"子夜歌四十二首 其三十三","f":"五言绝句","c":["夜长不得眠，明月何灼灼。","想闻欢唤声，虚应空中诺。"]},{"t":"欢闻变歌六首 其五","f":"五言绝句","c":["锲臂饮清血，牛羊持祭天。","没命成灰土，终不罢相怜。"]},{"t":"西洲曲","f":"五言古诗","c":["忆梅下西洲，折梅寄江北。","单衫杏子红，双鬓鸦雏色。","西洲在何处，两桨桥头渡。","日暮伯劳飞，风吹乌臼树。","树下即门前，门中露翠钿。","开门郎不至，出门采红莲。","采莲南塘秋，莲花过人头。","低头弄莲子，莲子青如水。","置莲怀袖中，莲心彻底红。","忆郎郎不至，仰首望飞鸿。","鸿飞满西洲，望郎上青楼。","楼高望不见，尽日栏干头。","栏干十二曲，垂手明如玉。","卷帘天自高，海水摇空绿。","海水梦悠悠，君愁我亦愁。","南风知我意，吹梦到西洲。"]},{"t":"青阳度 其二","f":"五言绝句","c":["碧玉捣衣砧，七宝金莲杵。","高举徐徐下，轻捣只为汝。"]},{"t":"孟珠 其三","f":"五言绝句","c":["阳春二三月，草与水同色。","道逢游冶郎，恨不早相识。"]},{"t":"杂诗","f":"五言绝句","c":["玉钗色未分，衫轻似露腕。","举袖欲障羞，回持理发乱。"]},{"t":"青阳度 其三","f":"五言绝句","c":["青荷盖绿水，芙蓉披红鲜。","下有并根藕，上生并头莲。"]},{"t":"长乐佳","f":"五言绝句","c":["红罗复斗帐，四角垂珠珰。","玉枕龙须席，郎眠何处床。"]},{"t":"子夜四时歌 冬歌十七首 其一","f":"五言绝句","c":["渊冰厚三尺，素雪覆千里。","我心如松柏，君情复何似。"]},{"t":"欢闻歌","f":"五言绝句","c":["遥遥天无柱，流漂萍无根。","单身如萤火，持底报郎恩。"]},{"t":"子夜四时歌 春歌二十首 其十七","f":"五言绝句","c":["明月照桂林，初花锦绣色。","谁能不相思，独在机中织。"]},{"t":"子夜四时歌 秋歌十八首 其十七","f":"五言绝句","c":["秋风入窗里，罗帐起飘飏。","仰头看明月，寄情千里光。"]},{"t":"子夜四时歌 夏歌二十首 其十","f":"五言绝句","c":["郁蒸仲暑月，长啸北湖边。","芙蓉始结叶，抛艳未成莲。"]},{"t":"平城歌","f":"古风","c":["平城之下亦诚苦。","七日不食。","不能彀弩。"]},{"t":"画一歌","f":"古风","c":["萧何为法，讲若画一。","曹参代之，守而勿失。","载其清靖，民以宁壹。"]},{"t":"民为淮南厉王歌","f":"古风","c":["一尺布尚可缝。","一斗粟尚可舂。","兄弟二人不相容。"]},{"t":"天下为卫子夫歌","f":"古风","c":["生男无喜。","生女无怒。","独不见卫子夫霸天下。"]},{"t":"郑白渠歌","f":"古风","c":["田于何所，池阳谷口。","郑国在前，白渠起后。","举锸如云，决渠为雨。","水流灶下，鱼跳入釜。","泾水一石，其泥数斗。","且溉且粪，长我禾黍。","衣食京师，忆万之口。"]},{"t":"颍川儿歌","f":"古风","c":["颍水清，灌氏宁。","颍水浊，灌氏族。"]},{"t":"牢石歌","f":"古风","c":["牢邪石邪，五鹿客邪。","印何累累，绶若若邪。"]},{"t":"上郡吏民为冯氏兄弟歌","f":"古风","c":["大冯君。","小冯君。","兄弟继踵相因循。","聪明贤知惠吏民。","政如鲁卫德化钧。","周公康叔犹二君。"]},{"t":"长安为尹赏歌","f":"五言绝句","c":["安所求之死，桓东少年场。","生时谅不谨，枯骨后何葬。"]},{"t":"长安百姓为王氏五侯歌","f":"古风","c":["五侯初起。","曲阳最怒。","坏决高都。","连竟外杜。","土山渐台西白虎。"]},{"t":"闾里为楼护歌","f":"七言古诗","c":["五侯治丧楼君卿。"]},{"t":"刘圣公宾客醉歌","f":"古风","c":["朝亨两都尉。","游徼后来用调羹味。"]},{"t":"匈奴歌","f":"古风","c":["亡我祁连山。","使我六畜不蕃息。","失我焉支山。","使我妇女无颜色。"]},{"t":"长沙人石虎谣","f":"古风","c":["石虎头截。","仓廪不阙。"]},{"t":"元帝时童谣","f":"古风","c":["井水溢，灭灶烟。","灌玉堂，流金门。"]},{"t":"长安谣","f":"古风","c":["伊徙雁。","鹿徙菟。","去牢与陈实无贾。"]},{"t":"成帝时童谣","f":"古风","c":["燕燕尾涏涏。","张公子时相见。","木门仓琅根。","燕飞来。","啄皇孙。","皇孙死。","燕啄矢。"]},{"t":"成帝时歌谣","f":"五言古诗","c":["邪径败良田，谗口乱善人。","桂树华不实，黄爵巢其颠。","故为人所羡，今为人所怜。"]},{"t":"汝南鸿隙陂童谣","f":"古风","c":["坏陂谁。","翟子威。","饭我豆食羹芋葵。","反乎覆。","陂当复。","谁云者。","两黄鹄。"]},{"t":"王莽末天水童谣","f":"古风","c":["出吴门。","望缇群。","见一蹇人言欲上天。","令天可上。","地上安得民。"]},{"t":"更始时南阳童谣","f":"古风","c":["谐不谐，在赤眉。","得不得，在河北。"]},{"t":"曹邱生引楚人谚","f":"古风","c":["得黄金百斤。","不如得季布一诺。"]},{"t":"汉人引鄙语","f":"古风","c":["不知为吏。","视已成事。"]},{"t":"韩安国引语","f":"古风","c":["虽有亲父。","安知不为虎。","虽有亲兄。","安知不为狼。"]},{"t":"桓宽引语","f":"古风","c":["厨有腐肉，国有饥民。","厩有肥马，路有馁人。"]},{"t":"桓宽引鄙语","f":"五言古诗","c":["贤者容不辱。"]},{"t":"《淮南子》引谚","f":"古风","c":["鸟穷则噣。","兽穷则?。","人穷则诈。"]},{"t":"邹阳引谚","f":"古风","c":["白头如新，倾盖如故。"]},{"t":"司马相如引谚","f":"古风","c":["家累千金，坐不垂堂。"]},{"t":"贡禹引俗语","f":"五言古诗","c":["何以孝弟为，财多而光荣。","何以礼义为，史书而仕宦。","何以谨慎为，勇猛而临官。"]},{"t":"司马迁引谚","f":"古风","c":["桃李不言，下自成蹊。"]},{"t":"司马迁引谚","f":"古风","c":["千金之子。","不死于市。"]},{"t":"司马迁引谚","f":"古风","c":["力田不如逢年，善仕不如遇合。"]},{"t":"司马迁引鄙语","f":"古风","c":["尺有所短，寸有所长。"]},{"t":"褚先生引谚","f":"古风","c":["美女入室，恶女之仇。"]},{"t":"褚先生引谚","f":"五言古诗","c":["相马失之瘦，相士失之穷。"]},{"t":"路温舒引俗语","f":"古风","c":["画地为狱。","议不入。","刻木为吏。","期不对。"]},{"t":"刘向引谚","f":"古风","c":["诫无垢，思无辱。"]},{"t":"薛宣引鄙语","f":"古风","c":["苟改不亲。","烦苦伤恩。"]},{"t":"刘辅引里语","f":"七言古诗","c":["腐木不可以为柱。","卑人不可以为主。"]},{"t":"王嘉引里谚","f":"古风","c":["千人所指。","无病而死。"]},{"t":"泛胜之引谚","f":"古风","c":["子欲富。","黄金覆。"]},{"t":"泛胜之引古语","f":"古风","c":["土长冒撅。","陈根可拔。","耕者急发。"]},{"t":"马廖引长安语","f":"五言古诗","c":["城中好高髻，四方高一尺。","城中好广眉，四方且半额。","城中好大袖，四方全匹帛。"]},{"t":"汉人为黄公语","f":"古风","c":["虎莫凶，有黄公。","猛兽回，黄公来。"]},{"t":"时人为应曜语","f":"古风","c":["南山四皓。","不如淮阳一老。"]},{"t":"关东为宁成号","f":"古风","c":["宁见乳虎。","无值宁成之怒。"]},{"t":"长安为韩嫣语","f":"古风","c":["苦饥寒。","逐弹丸。"]},{"t":"诸儒为朱云语","f":"古风","c":["五鹿狱狱。","朱云折其角。"]},{"t":"长安为王吉语","f":"古风","c":["东家有树，王阳妇去。","东家枣完，去妇复还。"]},{"t":"世称王贡语","f":"古风","c":["王阳在位，贡公弹冠。"]},{"t":"长安为萧朱王贡语","f":"古风","c":["萧朱结绶，王贡弹冠。"]},{"t":"吏民为赵张三王语","f":"古风","c":["前有赵张。","后有三王。"]},{"t":"邹鲁谚","f":"古风","c":["遗子黄金满籯。","不如一经。"]},{"t":"诸儒为匡衡语","f":"古风","c":["无说诗。","匡鼎来。","匡说诗。","解人颐。"]},{"t":"京师为诸葛丰语","f":"古风","c":["间何阔。","逢诸葛。"]},{"t":"诸儒为张禹语","f":"古风","c":["不欲为论。","念张文。"]},{"t":"长安为谷永楼护号","f":"五言古诗","c":["谷子云笔札。","楼君卿喉舌。"]},{"t":"时人为甄丰语","f":"古风","c":["夜半客。","甄长伯。"]},{"t":"长安为张竦语","f":"古风","c":["欲求封。","过张柏松。","力战斗。","不如巧为奏。"]},{"t":"时人为王莽语","f":"古风","c":["莽头秃。","帻施屋。"]},{"t":"东方为王匡廉丹语","f":"古风","c":["宁逢赤眉，不逢太师。","太师尚可，更始杀我。"]},{"t":"时人为蒋诩谚","f":"古风","c":["楚国二龚。","不如杜陵蒋翁。"]},{"t":"京师为杨雄语","f":"古风","c":["惟寂寞，自投阁。","爰清静，作符命。"]},{"t":"时人为扬雄桓谭语","f":"古风","c":["玩扬子云之篇。","乐于居千乘之官。","挟桓君之书。","富于积猗顿之财。"]},{"t":"更始时长安中语","f":"古风","c":["灶下养，中郎将。","烂羊胃，骑都尉。","烂羊头，关内侯。"]},{"t":"时人为戴遵语","f":"七言古诗","c":["关东大豪戴子高。"]},{"t":"三辅为张氏何氏语","f":"古风","c":["何氏算，张氏钩。","何氏肥，张氏瘦。"]},{"t":"时人为张氏谚","f":"古风","c":["相里张，多贤良。","积善应，子孙昌。"]},{"t":"桓谭引谚论巧习","f":"古风","c":["伏习象神。","巧者不过习者之门。"]},{"t":"桓谭引关东鄙语","f":"古风","c":["人间长安乐。","出门西向笑。","知肉味美。","对屠门而大嚼。"]},{"t":"安世房中歌","f":"古风","c":["大孝备矣。","休德昭清。","高张四县。","乐充宫庭。","芬树羽林。","云景杳冥。","金支秀华。","庶旄翠旌。","七始华始。","肃倡和声。","神来晏娭。","庶几是听。","粥粥音送。","细齐人情。","忽乘青玄。","熙事备成。","清思眑眑。","经纬冥冥。","我定历数。","人告其心。","敕身齐戒。","施教申申。","乃立祖庙。","敬明尊亲。","大矣孝熙。","四极爰轃。","王侯秉德。","其邻翼翼。","显明昭式。","清明鬯矣。","皇帝孝德。","竟全大功。","抚安四极。","海内有奸。","纷乱东北。","诏抚成饰。","武臣承德。","行乐交逆。","箫丂群慝。","肃为济哉。","盖定燕国。","大海荡荡水所归。","高贤愉愉民所怀。","大山崔。","百卉殖。","民何贵。","贵有德。","安其所。","乐终产。","乐终产。","世继绪。","飞龙秋。","游上天。","高贤愉。","乐民人。","丰草葽。","女罗施。","善何如。","谁能回。","大莫大。","成教德。","长莫长。","被无极。","雷震震。","电耀耀。","明德乡。","治本约。","治本约。","泽弘大。","加被宠。","咸相保。","德施大。","世曼寿。","都荔遂芳。","窅寙桂华。","孝奏天仪。","若日月光。","乘玄四龙。","回驰北行。","羽旄殷盛。","芬哉芒芒。","孝道随世。","我署文章。","冯冯翼翼。","承天之则。","吾易久远。","烛明四极。","慈惠所爱。","美若休德。","杳杳冥审。","克绰永福。","硙硙即即。","师象山则。","鸣呼孝哉。","案抚戎国。","蛮夷竭欢。","象来致福。","兼临是爱。","终无兵革。","嘉荐芳矣。","告灵飨矣。","告灵既飨。","德音孔臧。","惟德之臧。","建侯之常。","承保天休。","令问不忘。","皇皇鸿明。","荡侯休德。","嘉承天和。","伊乐厥福。","在乐不荒。","惟民之则。","浚则师德。","下民咸殖。","令问在旧。","孔容翼翼。","孔容之常。","承帝之明。","下民之乐。","子孙保光。","承顺温良。","受帝之光。","嘉荐令芳。","寿考不忘。","承帝明德。","师象山则。","云施称民。","永受厥福。","承容之常。","承帝之明。","下民安乐。","万寿无疆。"]},{"t":"练时日","f":"古风","c":["练时日，侯有望。","焫膋萧，延四方。","九重开，灵之斿。","垂惠恩，鸿祜休。","灵之车，结玄云。","驾飞龙，羽旄纷。","灵之下，若风马。","左仓龙，右白虎。","灵之来，神哉沛。","先以雨，般裔裔。","灵之至，庆阴阴。","相放?，震澹心。","灵已坐，五音饬。","虞至旦，承灵亿。","牲茧栗，粢盛香。","尊桂酒，宾八乡。","灵安留，吟青黄。","遍观此，眺瑶堂。","众嫭并，绰奇丽。","颜如荼，兆逐靡。","被华文，侧雾縠。","曳阿锡，佩珠玉。","侠嘉夜，茝兰芳。","澹容与，献嘉觞。"]},{"t":"帝临","f":"古风","c":["帝临中坛，四方承宇。","绳绳意变，备得其所。","清和六合，制数以五。","海内安宁，兴文匽武。","后土富媪，昭明三光。","穆穆优游，嘉服上黄。"]},{"t":"青阳邹子乐","f":"古风","c":["青阳开动，根荄以遂。","膏润并爱，跂行毕逮。","霆声发荣，岩处顷听。","枯槁复产，乃成厥命。","众庶熙熙，施及夭胎。","群生啿啿，惟春之祺。"]},{"t":"朱明","f":"古风","c":["朱明盛长，甫与万物。","桐生茂豫，靡有所诎。","敷华就实，既阜既昌。","登成甫田，百鬼迪尝。","广大建祀，肃雍不忘。","神若宥之，传世无疆。"]},{"t":"西颢","f":"古风","c":["西颢沆砀，秋气肃杀。","含秀垂颖，续旧不废。","奸伪不萌，祅孽伏息。","隅辟越远，四貉咸服。","既畏兹威，惟慕纯德。","附而不骄，正心翊翊。"]},{"t":"玄冥","f":"古风","c":["玄冥陵阴，蛰虫盖藏。","草木零落，抵冬降霜。","易乱除邪，革正异俗。","兆民反本，抱素怀朴。","条理信义，望礼五岳。","籍敛之时，掩收嘉谷。"]},{"t":"惟泰元","f":"古风","c":["惟泰元尊，媪神蕃厘。","经纬天地，作成四时。","精建日月，星辰度理。","阴阳五行，周而复始。","云风雷电，降甘露雨。","百姓蕃滋，咸循厥绪。","继统共勤，顺皇之德。","鸾路龙鳞，罔不肸饰。","嘉笾列陈，庶几宴享。","灭除凶灾，烈腾八荒。","钟鼓竽笙，云舞翔翔。","招摇灵旗，九夷宾将。"]},{"t":"天地","f":"古风","c":["天地并况。","惟予有慕。","爰熙紫坛。","思求厥路。","恭承禋祀。","缊豫为纷。","黼绣周张。","承神至尊。","千童罗舞成八溢。","合好效欢虞泰一。","九歌毕奏斐然殊。","鸣琴竽瑟会轩朱。","璆磬金鼓。","灵其有喜。","百官济济。","各敬厥事。","盛牲实俎进闻膏。","神奄留。","临须摇。","长丽前掞光耀明。","寒暑不忒况皇章。","展诗应律鋗玉鸣。","函宫吐角激徵清。","发梁扬羽申以商。","造兹新音永久长。","声气远条凤鸟鴹。","神夕奄虞盖孔享。"]},{"t":"日出入","f":"古风","c":["日出入安穷。","时世不与人同。","故春非我春。","夏非我夏。","秋非我秋。","冬非我冬。","泊如四海之池。","遍观是耶谓何。","吾知所乐。","独乐六龙。","六龙之调。","使我心若。","訾黄其何不徕下。"]},{"t":"天马","f":"古风","c":["太一况，天马下。","沾赤汗，沫流赭。","志俶傥，精权奇。","籋浮云，晻上驰。","体容与，迣万里。","今安匹，龙为友。","天马徕，从西极。","涉流沙，九夷服。","天马徕，出泉水。","虎脊两，化若鬼。","天马徕，历无草。","径千里，循东道。","天马徕，执徐时。","将摇举，谁与期。","天马徕，开远门。","竦予身，逝昆仑。","天马徕，龙之媒。","游闾阖，观玉台。"]},{"t":"天门","f":"古风","c":["天门开。","詄荡荡。","穆并骋。","以临飨。","光夜烛。","德信著。","灵寝平而鸿。","长生豫。","太朱涂广。","夷石为堂。","饰玉梢以舞歌。","体招摇若永望。","星留俞。","塞陨光。","照紫幄。","珠熉黄。","幡比翅回集。","贰双飞常羊。","月穆穆以金波。","日华耀以宣明。","假清风轧忽。","激长至重觞。","神裴回若留放。","殣冀亲以肆章。","函蒙祉福常若期。","寂漻上天知厥时。","泛泛滇滇从高斿。","殷勤此路胪所求。","佻正嘉吉弘以昌。","休嘉砰隐溢四方。","专精厉意逝九阂。","纷云六幕浮大海。"]},{"t":"景星","f":"古风","c":["景星显见。","信星彪列。","象载昭庭。","日亲以察。","参侔开阖。","爰推本纪。","汾脽出鼎。","皇祜元始。","五音六律。","依韦飨昭。","杂变并会。","雅声远姚。","空桑琴瑟结信成。","四兴迭代八风生。","殷殷钟石羽龠鸣。","河龙供鲤醇牺牲。","百末旨酒布兰生。","泰尊柘浆析朝酲。","微感心攸通修名。","周流常羊思所并。","穰穰复正直往宁。","冯蠵切和疏写平。","上天布施后土成。","穰穰丰年四时荣。"]},{"t":"齐房","f":"古风","c":["齐房产草，九茎连叶。","宫童效异，披图案谍。","玄气之精，回复此都。","蔓蔓日茂，芝成灵华。"]},{"t":"后皇","f":"古风","c":["后皇嘉坛，立玄黄服。","物发冀州，兆蒙祉福。","沇沇四塞，徦狄合处。","经营万意，咸遂厥宇。"]},{"t":"华烨烨","f":"古风","c":["华烨烨，固灵根。","神之斿，过天门。","车千乘，敦昆仑。","神之出，排玉房。","周流杂，拔兰堂。","神之行，旌容容。","骑沓沓，般纵纵。","神之徕，泛翊翊。","甘露降，庆云集。","神之揄，临坛宇。","九疑宾，夔龙舞。","神安坐，翔吉时。","共翊翊，合所思。","神嘉虞，申贰觞。","福滂洋，迈延长。","沛施佑，汾之阿。","扬金光，横泰河。","莽若云，增扬波。","遍胪骧，腾天歌。"]},{"t":"五神","f":"古风","c":["五神相，包四邻。","土地广，扬浮云。","扢嘉坛，椒兰房。","璧玉精，垂华光。","益意年，美始兴。","交于神，若有承。","广宣延，咸毕觞。","灵舆位，偃蹇骧。","卉汨胪，析奚遗。","淫渌泽，淫然归。"]},{"t":"朝陇首","f":"古风","c":["朝陇首，览西垠。","雷电尞，获白麟。","爰五止，显黄德。","图匈虐，熏鬻殛。","辟流离，抑不详。","宾百僚，山河飨。","掩回辕，鬗长驰。","腾雨师，洒路陂。","流星陨，感惟风。","籋归云，抚怀心。"]},{"t":"象载瑜","f":"古风","c":["象载瑜，白集西。","食甘露，饮荣泉。","赤雁集，六纷员。","殊翁杂，五采文。","神所见，施祉福。","登蓬莱，结无极。"]},{"t":"赤蛟","f":"古风","c":["赤蛟绥，黄华盖。","露夜零，书晻濭。","百君礼，六龙位。","勺椒浆，灵已醉。","灵既享，锡吉祥。","芒芒极，降嘉觞。","灵殷殷，烂扬光。","延寿命，永未央。","杳冥冥，塞六合。","泽汪濊，辑万国。","灵禗禗，象舆?。","票然逝，旗逶蛇。","礼乐成，灵将归。","托玄德，长无衰。"]},{"t":"客示桓麟诗","f":"古风","c":["甘罗十二，杨乌九龄。","昔有二子，今则桓生。","参差等踪，异世齐名。"]},{"t":"渔阳民为张堪歌","f":"古风","c":["桑无附枝，麦穗两歧。","张君为政，乐不可支。"]},{"t":"临淮吏人为宋晖歌","f":"古风","c":["彊直自遂，南阳朱季。","吏畏其威，民怀其惠。"]},{"t":"凉州民为樊晔歌","f":"五言律诗","c":["游子常苦贫，力子天所富。","宁见乳虎穴，不入冀府寺。","大笑期必死，忿怒或见置。","嗟我樊府君，安可再遭值。"]},{"t":"董少平歌","f":"七言古诗","c":["枹鼓不鸣董少平。"]},{"t":"郭乔卿歌","f":"古风","c":["厥德仁明郭乔卿。","中正朝廷上下一平。"]},{"t":"蜀中为费贻歌","f":"古风","c":["节义至仁费奉君。","不仕乱世。","不避恶君。"]},{"t":"鲍司隶歌","f":"古风","c":["鲍氏骢。","三人司隶再入公。","马虽瘦。","行步工。"]},{"t":"通博南歌","f":"古风","c":["汉德广，开不宾。","度博南，越兰津。","度兰仓，为他人。"]},{"t":"蜀郡民为廉范歌","f":"古风","c":["廉叔度。","来何暮。","不禁火。","民安作。","平生无襦今五裤。"]},{"t":"苍梧人为陈临歌二首 其一","f":"七言古诗","c":["苍梧陈君恩广大。","令死罪囚有后代。","德参古贤天报施。"]},{"t":"苍梧人为陈临歌二首 其二","f":"七言古诗","c":["苍梧府君惠反死。","能令死人不绝嗣。"]},{"t":"乡人为秦护歌","f":"古风","c":["冬无裤。","有秦护。"]},{"t":"魏郡舆人歌","f":"古风","c":["我有枳棘，岑君伐之。","我有蟊贼，岑君遏之。","狗吠不惊，足下生蝥。","合脯鼓腹，焉知凶灾。","我喜我生，独于斯时。","美矣岑君，于戏休兹。"]},{"t":"范史云歌","f":"七言古诗","c":["甑中生尘范史云，釜中生鱼范莱芜。"]},{"t":"顺阳吏民为刘陶歌","f":"古风","c":["悒然不乐，思我刘君。","何时复来，安此下民。"]},{"t":"董逃歌","f":"五言古诗","c":["承乐世董逃。","游四郭董逃。","蒙天恩董逃。","带金紫董逃。","行谢恩董逃。","整车骑董逃。","垂欲发董逃。","与中辞董逃。","出西门董逃。","瞻宫殿董逃。","望京城董逃。","日夜绝董逃。","心摧伤董逃。"]},{"t":"皇甫嵩歌","f":"楚辞体","c":["天下大乱兮市为墟。","母不保子兮妻失夫。","赖得皇甫兮复安居。"]},{"t":"洛阳人为祝良歌","f":"古风","c":["天久不雨，烝民失所。","天王自出，祝令特苦。","精符感应，滂沱而下。"]},{"t":"巴人歌陈纪山","f":"五言古诗","c":["筑室载直梁，国人以贞真。","邪娱不扬目，狂行不动身。","奸轨僻乎远，理义协乎民。"]},{"t":"汲县长老为崔瑗歌","f":"五言古诗","c":["上天降神明，锡我仁慈父。","临民布德泽，恩惠施以序。","穿沟广溉灌，决渠作甘雨。"]},{"t":"崔君歌","f":"楚辞体","c":["讠毕治小序兮稼穑分。","天赐我兮此崔君。"]},{"t":"彭子阳歌","f":"古风","c":["时岁仓卒。","盗贼纵横。","大戟强弩不可当。","赖遇贤令彭子阳。"]},{"t":"王世容歌","f":"古风","c":["王世容，治无双。","省徭役，盗贼空。"]},{"t":"巴郡人为吴资歌","f":"五言绝句","c":["习习晨风动，澍雨润禾苗。","我后恤时务，我人以优饶。"]},{"t":"又歌","f":"五言绝句","c":["望远忽不见，惆怅当徘徊。","恩泽实难忘，悠悠心永怀。"]},{"t":"六县吏人为爰珍歌","f":"古风","c":["我有田畴，爰父殖置。","我有子弟，爰父教诲。"]},{"t":"后时蜀中童谣","f":"古风","c":["黄牛白腹。","五铢当复。"]},{"t":"会稽童谣","f":"古风","c":["弃我戟，捐我矛。","盗贼尽，吏皆休。"]},{"t":"会稽童谣","f":"七言古诗","c":["城上乌鸣哺父母。","府中诸吏皆孝友。"]},{"t":"河内谣","f":"古风","c":["王稚子，世未有。","平徭役，百姓喜。"]},{"t":"蜀郡童谣","f":"古风","c":["两日出。","天兵戢。"]},{"t":"益都民为王忳谣","f":"七言古诗","c":["信哉少林世为遇。","飞被走马与鬼语。"]},{"t":"恒农童谣","f":"古风","c":["君不我忧，人何以休。","不行界署，焉知人处。"]},{"t":"桓帝初天下童谣","f":"古风","c":["小麦青青大麦枯。","谁当获者妇与姑。","丈夫何在西击胡。","吏卖马。","君具车。","请为诸君鼓咙胡。"]},{"t":"桓帝初城上乌童谣","f":"古风","c":["城上乌。","尾毕逋。","公为吏。","子为徒。","一徒死。","百乘车。","车班班。","入河间。","河间姹女工数钱。","以钱为室金为堂。","石上慊慊舂黄粱。","梁下有悬鼓。","我欲击之丞卿怒。"]},{"t":"桓帝时京都童谣","f":"七言古诗","c":["游平卖印自有平，不辟豪贤及大姓。"]},{"t":"桓帝末京都童谣","f":"古风","c":["白盖小车何延延。","河间来合谐。","河间来合谐。"]},{"t":"桓帝末京都童谣","f":"古风","c":["茅田一顷中有井。","四方纤纤不可整。","嚼复嚼。","今年尚可后年饶。"]},{"t":"乡人谣","f":"古风","c":["天下规矩。","房伯武。","因师获印。","周仲进。"]},{"t":"二郡谣","f":"七言绝句","c":["汝南太守范孟博，南阳宗资主画诺。","南阳太守岑公孝，弘农成瑨但坐啸。"]},{"t":"太学中谣五首 其一 三君","f":"七言古诗","c":["天下忠诚窦游平。","天下义府陈仲举。","天下德弘刘仲承。"]},{"t":"太学中谣五首 其二 八俊","f":"七言律诗","c":["天下模楷李元礼，天下英秀王叔茂。","天下良辅杜周甫，天下冰凌朱季陵。","天下忠贞魏少英，天下好交荀伯条。","天下稽古刘伯祖，天下才英赵仲经。"]},{"t":"太学中谣五首 其三 八顾","f":"七言律诗","c":["天下和雍郭林宗，天下慕恃夏子治。","天下英藩尹伯元，天下清苦羊嗣祖。","天下宝金刘叔林，天下雅志蔡孟喜。","天下卧虎巴恭祖，天下通儒宗孝初。"]},{"t":"太学中谣五首 其四 八及","f":"七言古诗","c":["海内贵珍陈子鳞。","海内忠烈张元节。","海内謇谔范孟博。","海内通士檀文友。","海内彬彬范仲真。","海内珍好岑公孝。","海内所称刘景升。"]},{"t":"太学中谣五首 其五 八厨","f":"古风","c":["海内贤智王伯义。","海内修整蕃嘉景。","海内贞良秦平王。","海内珍奇胡母季皮。","海内光光刘子相。","海内依怙王文祖。","海内严恪张孟卓。","海内清明度博平。"]},{"t":"京兆民为李庄歌","f":"古风","c":["我府君。","惠如春。","盛如唐。"]},{"t":"灵帝末京都童谣","f":"古风","c":["侯非侯。","王非王。","千乘万骑上北芒。"]},{"t":"献帝初京都童谣","f":"古风","c":["千里草，何青青。","十日卜，不得生。"]},{"t":"献帝初童谣","f":"古风","c":["燕南垂。","赵北际。","中央不合大如砺。","唯有此中可避世。"]},{"t":"初平中长安谣","f":"古风","c":["头白皓然，食不充粮。","裹衣蹇裳，当还故乡。","圣王悯念，悉用补郎。","舍是布衣，被彼玄黄。"]},{"t":"兴平中吴中童谣","f":"古风","c":["黄金车，班兰耳。","开阊门，出天子。"]},{"t":"建安初荆州童谣","f":"七言古诗","c":["八九年间始欲衰。","至十三年无孑遗。"]},{"t":"汉末洛中童谣","f":"五言绝句","c":["虽有千黄金，无如我斗粟。","斗粟自可饱，千金何所直。"]},{"t":"汉末江淮间童谣","f":"古风","c":["大兵如市，人死如林。","持金易粟，粟贵于金。"]},{"t":"京师为光禄茂才谣","f":"古风","c":["欲得不能。","光禄茂才。"]},{"t":"阎君谣","f":"古风","c":["阎君赋政，既明且昶。","去苛去碎，动以礼让。"]},{"t":"东门奂谣","f":"古风","c":["东门奂，取吴半。","吴不足，济阴续。"]},{"t":"商子华谣","f":"七言古诗","c":["石里之勇商子华。","暴虎见之藏爪牙。"]},{"t":"时人谣","f":"七言古诗","c":["五侯之斗血成江。"]},{"t":"擿洛谣","f":"七言古诗","c":["剡者配姬以放贤。","山崩水溃纳小人。","家伯罔主异哉震。"]},{"t":"京师为唐约谣","f":"古风","c":["治身无嫌。","唐仲谦。"]},{"t":"蒋横遘祸时童谣","f":"古风","c":["君用谗慝，忠烈是殛。","鬼怨神怒，妖气充塞。"]},{"t":"锡山古谣","f":"古风","c":["有锡兵。","无锡宁。"]},{"t":"时人为三茅君谣","f":"五言古诗","c":["茅山连金陵，江湖据下流。","三神乘白鹤，各在一山头。","佳雨灌畦稻，陆地亦复周。","妻子保堂室，使我无百忧。","白鹤翔青天，何时复来游。"]},{"t":"谚语】【光武述时人语","f":"古风","c":["关东觥觥。","《郭子》横。"]},{"t":"时人为郭况语","f":"七言古诗","c":["洛阳多钱郭氏室。","月夜书昼富无匹。"]},{"t":"时人为郭况语","f":"古风","c":["洛阳多钱。","郭氏万千。"]},{"t":"光武引谚","f":"古风","c":["贵易交，富易妻。"]},{"t":"宋弘引语","f":"七言古诗","c":["贫贱之知不可忘。","糟糠之妻不下堂。"]},{"t":"南阳为杜师语","f":"古风","c":["前有召父。","后有杜母。"]},{"t":"时人为廉范语","f":"古风","c":["前有管鲍，后有庆廉。"]},{"t":"章帝引谚","f":"古风","c":["作舍道边，三年不成。"]},{"t":"班固引谚论经方","f":"古风","c":["有病不治。","常得中医。"]},{"t":"班昭女诫引鄙谚","f":"古风","c":["生男如狼，犹恐其尪。","生女如鼠，犹恐其虎。"]},{"t":"王逸引谚","f":"古风","c":["政如冰霜，奸轨消亡。","威如雷霆，寇贼不生。"]},{"t":"虞诩引谚","f":"古风","c":["关西出将。","关东出相。"]},{"t":"王符引谚论得贤","f":"古风","c":["一犬吠形。","百犬吠声。"]},{"t":"京师为黄香号","f":"古风","c":["天下无双，江夏黄童。"]},{"t":"人为高慎语","f":"古风","c":["嶷然不语。","名高孝甫。"]},{"t":"颍川为荀爽语","f":"古风","c":["荀氏八龙，慈明无双。"]},{"t":"崔实引农家谚","f":"古风","c":["上火不落。","下火滴沰。"]},{"t":"崔寔引里语","f":"古风","c":["一岁再赦，奴儿喑恶。"]},{"t":"李固引语","f":"古风","c":["善人在患。","饥不及餐。"]},{"t":"益州长为尹就谚","f":"古风","c":["虏来尚可。","尹来杀我。"]},{"t":"天下为贾彪语","f":"古风","c":["贾氏三虎。","伟节最怒。"]},{"t":"应劭引俚语论正失","f":"古风","c":["狐欲渡河。","无奈尾河。"]},{"t":"应劭引俚语论愆礼","f":"古风","c":["妇死腹悲。","唯身知之。"]},{"t":"应劭引里语论日蚀","f":"古风","c":["不救蚀者，出行遇语。"]},{"t":"应劭引里语论主客","f":"古风","c":["越陌度阡，更为客主。"]},{"t":"应劭引里语论谳狱","f":"古风","c":["县官漫漫。","冤死者半。"]},{"t":"应劭引里语","f":"七言古诗","c":["仕宦不止车生耳。"]},{"t":"应劭引语论正失","f":"古风","c":["金不可作。","世不可度。"]},{"t":"时人为庞氏语","f":"古风","c":["庐里诸庞。","凿井得铜。","买奴得翁。"]},{"t":"民为二殽语","f":"古风","c":["东殽西殽。","渑池所高。"]},{"t":"南阳为卫修陈茂语","f":"古风","c":["卫修有事，陈茂治之。","卫修无事，陈茂杀之。"]},{"t":"公沙六龙","f":"古风","c":["公沙六龙，天下无双。"]},{"t":"民为五门语","f":"古风","c":["苑中三公，馆下二卿。","五门嚄嚄，但闻豚声。"]},{"t":"时人为作奏语","f":"古风","c":["作奏虽工。","宜去葛龚。"]},{"t":"高诱引谚论毁誉","f":"古风","c":["欲人不知。","莫如不为。"]},{"t":"武陵人为黄氏兄弟谚","f":"古风","c":["天有冬夏，人有二黄。"]},{"t":"时人为杨氏四子语","f":"古风","c":["三苗不止。","四珍复起。"]},{"t":"羊元引谚","f":"古风","c":["孤犊触乳。","骄子詈母。"]},{"t":"古谚","f":"古风","c":["虽有神药，不如少年。","虽有珠玉，不如金钱。"]},{"t":"时人为郭典语","f":"古风","c":["郭君围堑，董将不许。","几令狐狸，化为豺虎。","赖我郭君，不畏强御。","转机之间，敌为穷虏。","猗猗惠君，实完疆土。"]},{"t":"时人为周泽语","f":"古风","c":["居世不谐为太常妻。","一岁三百六十日。","三百五十九日齐。","一日不齐醉如泥。","既作事。","复低迷。"]},{"t":"崔实引语","f":"古风","c":["小民发如韭。","剪复生。","头如鸡。","割复鸣。","吏不必可畏。","从来必可轻。","奈何欲望平。"]},{"t":"时人为桓典语","f":"古风","c":["行行且止。","避骢御史。"]},{"t":"益都乡里为柳宗语","f":"古风","c":["得黄金一笥。","不如为柳伯骞所识。"]},{"t":"宣城为封使君语","f":"古风","c":["无作封使君。","生来治民死食民。"]},{"t":"益都为任文公语","f":"古风","c":["任文公，智无双。"]},{"t":"马皇后引俗语","f":"古风","c":["时无赭，浇黄土。"]},{"t":"崔寔引里语","f":"古风","c":["州郡记，如霹雳。","得诏书，但挂壁。"]},{"t":"崔寔引农语 其一","f":"古风","c":["二月昏，参星夕。","杏花盛，桑椹赤。"]},{"t":"崔寔引农语 其二","f":"古风","c":["河射角，堪夜作。","犁星没，水生骨。"]},{"t":"京师为袁成谚","f":"古风","c":["事不谐。","诣文开。"]},{"t":"天下为四侯语","f":"古风","c":["左回天，具独坐。","徐卧虎，唐两堕。"]},{"t":"京师为张盘语","f":"古风","c":["闻清白。","张子石。"]},{"t":"人为徐闻县谚","f":"古风","c":["欲拔贫。","诣徐闻。"]},{"t":"京师为鲍永鲍恢语","f":"七言古诗","c":["贵戚敛手避二鲍。"]},{"t":"时人为折氏谚","f":"古风","c":["折氏客谁。","朱云卿段节英。","中有佃子赵仲平。","但说天文论五经。"]},{"t":"王符引谚论守边","f":"七言古诗","c":["痛不著身言忍之，钱不出家言与之。"]},{"t":"三府为朱震语","f":"七言古诗","c":["车如鸡栖马如狗。","疾恶如风朱伯厚。"]},{"t":"时人为贡举语","f":"七言古诗","c":["古人欲达勤诵经。","今民图官勉治生。"]},{"t":"赵岐引南阳旧语","f":"古风","c":["前队大夫范仲公。","盐蒜果共一筒。"]},{"t":"考城为仇览谚","f":"七言古诗","c":["父母何在在我庭。","化我鸤枭哺所生。"]},{"t":"时人为孔氏兄弟语","f":"七言绝句","c":["鲁国孔氏好读经。","兄弟讲诵皆可听。","学士来者有声名。","不过孔氏那得成。"]},{"t":"华容女子狱中歌吟","f":"七言古诗","c":["不意李立为贵人。"]},{"t":"阚骃引语","f":"七言古诗","c":["仕宦不偶值冀部，幽冀之人钝如椎。"]},{"t":"王符引谚论考绩","f":"五言古诗","c":["曲木恶直绳，重罚恶明证。"]},{"t":"时人为王符语","f":"五言古诗","c":["徒见二千石。","不如一缝掖。"]},{"t":"乡里为雷义陈重语","f":"五言古诗","c":["胶漆自谓坚，不如雷与陈。"]},{"t":"郑玄引俗语","f":"五言古诗","c":["隐疾难为医。"]},{"t":"时人为吕布语","f":"五言古诗","c":["人中有吕布。","马中有赤兔。"]},{"t":"关中为游殷谚","f":"古风","c":["生有知人之明。","死有贵神之灵。"]},{"t":"京师为戴凭语","f":"古风","c":["解经二不穷。","戴侍中。"]},{"t":"京师为井丹语","f":"古风","c":["五经纷纶。","井大春。"]},{"t":"时人为王君公语","f":"古风","c":["避世墙东。","王君公。"]},{"t":"京师为杨政语","f":"古风","c":["说经铿铿。","杨子行。"]},{"t":"京师为祁圣元号","f":"古风","c":["论难僠僠。","祁圣元。"]},{"t":"寿春乡里为召驯语","f":"古风","c":["德得恂恂。","召伯春。"]},{"t":"时人为丁鸿语","f":"古风","c":["殿中无双。","丁孝公。"]},{"t":"京兆乡里为冯豹语","f":"古风","c":["道德彬彬。","冯仲文。"]},{"t":"诸儒为贾逵语","f":"古风","c":["问事不休。","贾长头。"]},{"t":"关中为鲁丕语","f":"古风","c":["五经复兴。","鲁叔陵。"]},{"t":"诸儒为杨震语","f":"古风","c":["关西孔子。","杨伯起。"]},{"t":"时人为许慎语","f":"古风","c":["五经无双。","许叔重。"]},{"t":"京师为周举语","f":"古风","c":["五经从横。","周宣光。"]},{"t":"京师为胡广语","f":"古风","c":["万事不理。","问伯始。","天下中庸。","有胡公。"]},{"t":"时人为任安语","f":"古风","c":["欲知仲桓。","问任安。","居今行古。","任定祖。"]},{"t":"时人为陈嚣语","f":"古风","c":["关东说诗。","陈君期。"]},{"t":"诸儒为刘恺语","f":"古风","c":["难经伉伉。","刘太常。"]},{"t":"人为许晏谚","f":"古风","c":["殿上成群。","许伟君。"]},{"t":"乡里为茨充号","f":"古风","c":["一马两车。","茨子河。"]},{"t":"时人为缪文雅语","f":"古风","c":["素车白马。","缪文雅。"]},{"t":"敦煌乡人为曹全谚","f":"古风","c":["重亲致欢。","曹景完。"]},{"t":"将归操","f":"楚辞体","c":["狄之水兮风扬波。","船楫颠倒更相加。","归来归来胡为斯。"]},{"t":"陬操","f":"古风","c":["周道衰微，礼乐陵迟。","文武既坠，吾将焉归。","周游天下，靡邦可依。","凤鸟不识，珍宝枭鸱。","眷然顾之，惨然心悲。","巾车命驾，将适唐都。","黄河洋洋，攸攸之鱼。","临津不济，还辕息鄹。","伤予道穷，哀彼无辜。","翱翔于卫，复我旧庐。","从我所好，其乐只且。"]},{"t":"猗兰操","f":"古风","c":["习习谷风，以阴以雨。","之子于归，远送于野。","何彼苍天，不得其所。","逍遥九州，无有定处。","世人暗蔽，不知贤者。","年纪迈逝，一身将老。"]},{"t":"龟山操","f":"楚辞体","c":["予欲望鲁兮龟山蔽之。","手无斧柯。","奈龟山何。"]},{"t":"越裳操","f":"古风","c":["于戏嗟嗟。","非旦之力。","乃文王之德。"]},{"t":"拘幽操","f":"楚辞体","c":["殷道溷溷浸浊烦兮。","朱紫相合不别分兮。","迷乱声色信谗言兮。","炎炎之虐使我愆兮。","幽闭牢阱由其言兮。","无辜桎梏谁所宣兮。","进我四人忧勤勤兮。","得此珍玩且解大患兮。","仓皇迤命遗后昆兮。","作此象变兆在昌兮。","钦承祖命天不丧兮。","遂临下土在圣明兮。","讨暴除乱诛逆王兮。"]},{"t":"履霜操","f":"楚辞体","c":["履朝霜兮采晨寒。","考不明其心兮听谗言。","孤恩别离兮摧肺肝。","何辜皇天兮遭斯愆。","痛殁不同兮恩有偏。","谁说顾兮知我冤。"]},{"t":"雉朝飞操","f":"楚辞体","c":["雉朝飞。","鸣相和。","雌雄群游于山阿。","我独何命兮未有家。","时将暮兮可奈何。","嗟嗟暮兮可奈何。"]},{"t":"别鹤操","f":"楚辞体","c":["将乖比翼兮隔天端。","山川悠远兮路漫漫。","揽衣不寐兮食忘餐。"]},{"t":"列女引","f":"楚辞体","c":["忠谏行兮正不邪，众妾夸兮继嗣多。"]},{"t":"贞女引","f":"楚辞体","c":["菁菁茂木隐独荣兮。","变化垂枝含秀英兮。","修身养行建令名兮。","厥道不移善恶并兮。","屈躬就浊世彻清兮。","怀忠见疑何贪生兮。"]},{"t":"辟历","f":"楚辞体","c":["疾雨盈河。","辟历下臻。","洪水浩浩滔厥天。","铿?隆愧。","隐隐阗阗。","国将亡兮丧厥年。"]},{"t":"箕山操","f":"楚辞体","c":["登彼箕山兮瞻望天下。","山川丽崎。","万物还普。","日月运照。","靡不记睹。","游放其间。","何所却虑。","叹彼唐尧。","独自愁苦。","劳心九州。","忧勤后土。","谓余钦明。","传禅易祖。","我乐如何。","盖不盼顾。","河水流兮缘高山。","甘瓜施兮弃绵蛮。","高林肃兮相错连。","居此之处傲尧君。"]},{"t":"文王受命","f":"楚辞体","c":["翼翼翱翔彼鸾皇兮，衔书来游以命昌兮。","瞻天案图殷将亡兮，苍苍昊天始有萌兮。","神连精合谋于房兮，与我之业望羊来兮。"]},{"t":"思亲操","f":"楚辞体","c":["陟彼历山兮崔嵬。","有鸟翔兮高飞。","瞻彼鸠兮徘徊。","河水洋洋兮清冷。","深谷鸟鸣兮嘤嘤。","设罝张■兮思我父母力耕。","日与月兮往如驰。","父母远兮吾将安归。"]},{"t":"仪凤歌","f":"楚辞体","c":["凤皇翔兮于紫庭。","余何德兮以感灵。","赖先人兮恩泽臻。","于胥乐兮民以宁。","凤皇来兮百兽晨。"]},{"t":"龙蛇歌","f":"古风","c":["有龙矫矫，遭天谴怒。","卷逃鳞甲，来遁于下。","志愿不得，与蛇同伍。","龙蛇俱行，周遍山野。","龙遭饥饿，蛇割腓股。","龙得升天，安厥房产。","蛇独抑摧，沈滞泥土。","仰天怨望，惆怅悲苦。","非乐龙伍，怪不盼顾。"]},{"t":"龙蛇歌","f":"古风","c":["有龙矫矫。","将失其所。","有蛇从之。","周流天下。","龙既入深渊。","得其安所。","蛇脂尽乾。","独不得甘雨。"]},{"t":"龙蛇歌","f":"古风","c":["有龙矫矫，而失其所。","有蛇从之，而啖其口。","龙既升云，蛇独泥处。"]},{"t":"龙蛇歌","f":"古风","c":["有龙矫矫，遭天谴怒。","三蛇从之，一蛇割股。","二蛇入国，厚蒙爵士。","馀有一蛇，弃于草莽。"]},{"t":"芑梁妻歌","f":"楚辞体","c":["乐莫乐兮新相知。","悲莫悲兮生别离。","哀感皇天兮城为隳。"]},{"t":"信立","f":"楚辞体","c":["悠悠沂水经荆山兮。","精气郁泱谷岩岩兮。","中有神宝灼明明兮。","穴山采玉难为功兮。","于何献之楚先王兮。","遇王暗昧信谗言兮。","断截两足离余身兮。","俯仰嗟叹心摧伤兮。","紫之乱朱粉墨同兮。","空山歔欷涕龙钟兮。","天鉴孔明竟以彰兮。","沂水滂沌流于汶兮。","进宝得刑足离分兮。","去封立信守休芸兮。","断者不续岂不冤兮。"]},{"t":"归耕操","f":"楚辞体","c":["歔欷归耕来兮。","安所耕历山盘兮。","以晏父母我心博兮。"]},{"t":"引声歌","f":"古风","c":["天地之道，近在胸臆。","呼噏精神，以养九德。","渴不求饮，饥不索食。","避世守道，志洁如玉。","卿相之位，难可直当。","岩岩之石，幽而清凉。","枕块寝处，乐在其央。","寒凉固回，可以久长。"]},{"t":"霍将军歌","f":"楚辞体","c":["四夷既获诸夏康兮。","国家安宁乐无央兮。","载戢干戈弓矢藏兮。","麒麟来臻凤皇翔兮。","与天相保永无疆兮。","亲亲百年各延长兮。"]},{"t":"获麟歌","f":"楚辞体","c":["唐虞世兮麟凤游。","今非其时来何求。","麟兮麟兮我心忧。"]},{"t":"失题","f":"楚辞体","c":["俟罪斯国志愿得兮。","庶此太康皆为力兮。"]},{"t":"饭牛歌","f":"古风","c":["南山矸。","白石䃹。","生不逢尧与舜禅。","短而单衣裁至骭。","长夜漫漫何时旦。"]},{"t":"失题","f":"古风","c":["鹓彼鸣鹣。","在严山之唫。"]},{"t":"神人畅","f":"楚辞体","c":["清庙穆兮承予宗。","百僚肃兮于寝堂。","醊祷进福求年丰。","有?在坐敕予为?在玄中。","钦哉昊天德不隆。","承命任禹写中宫。"]},{"t":"南风操","f":"楚辞体","c":["反彼三山兮商岳嵯峨。","天降五老兮迎我来歌。","有黄龙兮自出于河。","负书图兮委蛇罗沙。","案图观谶兮闵天嗟嗟。","击石拊韶兮沦幽洞微。","鸟兽跄跄兮凤凰来仪。","凯风自南兮喟其增悲。"]},{"t":"箕子操","f":"古风","c":["嗟嗟纣为无道杀比干。","嗟重复嗟。","独柰何。","漆身为厉。","被发以佯狂。","今柰宗庙保。","天乎天哉。","欲负石自投河。","嗟复嗟柰社稷何。"]},{"t":"克商操","f":"楚辞体","c":["上告皇天兮可以行乎。"]},{"t":"水仙操","f":"楚辞体","c":["翳洞渭兮流澌濩，舟楫逝兮仙不还。","移形素兮蓬莱山，歍钦伤宫仙石还。"]},{"t":"伯姬引","f":"楚辞体","c":["嘉名洁兮行弥章。","托节鼓兮令躬丧。","歍钦何辜遇斯殃。","嗟嗟柰何罹斯殃。"]},{"t":"思归引","f":"楚辞体","c":["涓涓泉水。","流及于淇兮。","有怀于卫。","靡日不思。","执节不移兮行不隳。","砛轲何辜兮离厥菑。","嗟乎何辜兮离厥菑。"]},{"t":"琴引","f":"楚辞体","c":["酒坐俱勿往。","听吾琴之所言。","舒长袖似舞兮乃褕袂何曼。","奏章而却逢兮愿瞻心之所欢。","借连娟之寒态兮假卮酒酌五般。","泣喻而妖兮纳其声声丽颜。","长㯓兮叹曰骑。","美人旖旎纷嬆。","枻霜罗衣兮羽旄。","夜褒圭玉珠参差。","妙丽兮被云髾。","登高台兮望青挨。","常羊啖还何厌兮归来。"]},{"t":"岐山操","f":"楚辞体","c":["狄戎侵兮土地迁移。","邦邑适于岐山。","烝民不忧兮谁者知。","嗟嗟柰何兮予命遭斯。"]},{"t":"绥山谣","f":"古风","c":["得绥山一桃。","虽不得仙。","亦足亦豪。"]},{"t":"长安中谣","f":"古风","c":["见乞儿与美酒。","以免破屋之咎。"]},{"t":"里语","f":"古风","c":["年未半。","枝不汗。"]},{"t":"赤雀辞","f":"古风","c":["安公安公。","冶与天通。","七月七日。","迎汝以赤龙。"]},{"t":"鬼神】【崔少府女赠卢充诗","f":"五言古诗","c":["煌煌灵芝质，光丽何猗猗。","华艳当时显，嘉异表神奇。","含英未及秀，中夏罹霜萎。","荣曜长幽灭，世路永无施。","不悟阴阳运，哲人忽来仪。","会浅离别速，皆由灵与祗。","何以赠余亲，金鋺可养儿。","爱恩从此别，断绝伤肝碑。"]},{"t":"咏谯君黄诗","f":"五言绝句","c":["肃肃清节士，执德实固贞。","违恶以授命，没世遗令声。"]},{"t":"伤三贞诗","f":"古风","c":["间关黄鸟，爰集于树。","窈窕淑女，是绣是黼。","惟彼绣黼，其心匪石。","嗟尔临川，邈不可获。"]},{"t":"风巴郡太守诗","f":"古风","c":["明明上天，下土是亲。","帝选元后，求定安民。","孰可不念，祸福由人。","愿君奉诏，惟德日新。"]},{"t":"思治诗","f":"五言绝句","c":["混混浊沼鱼，习习激清流。","温温乱国民，业业仰前修。"]},{"t":"张公神碑歌","f":"楚辞体","c":["綦水汤汤扬清波。","东流□折□于河。","□□□□□朝歌。","县以吉静无秽瑕。","公□守相驾蜚鱼。","往来悠忽遂熹娱。","佑此兆民宁厥居。","出自綦□□□□。","松柏郁茂兰公□。","□神往来乘浮云。","种德收福惠斯民。","家饶户富无□贫。","畺界家静和睦口。","朝歌荡阴及犁阳。","三女所处各殊方。","三门鼎列推其乡。","时携甥幼归候公。","夫人□□□容□。","□□□□飨□觞。","穆风屑兮起坛旁。","乐吏民兮永未央。","鹿呦呦兮□□庭。","文乐乐兮□□□。","饮清泉兮□□□。","见□伏兮不骇惊。","惟公德兮之所宁。","上陵庙兮助三牲。","天时和兮甘露冷。","日番□兮无亏倾。","□□蜚兮朱鸟栖。","□□荣兮鸣喈喈。","䳒鹄剿兮乳徘徊。","给御卵兮献于西。","惟公德兮之所怀。","池水□兮钓台粲。","四角楼兮临深涧。","鱼岌岌兮踊跃见。","振鳞尾兮游旰旰。","时钓取兮给烹献。","惟公德兮之所衍。","栗萧草兮丛铺陈。","新美萌兮香苾芬。","蕙草生兮满园田。","竞苔茗兮给万钱。","惟公德兮之所□。","门堂郁兮文耀光。","公神赫兮坐东方。","明暴视兮俨卬卬。","夫人□女兮列在旁。","陈君处北兮从官□。","车骑骆驿兮交错重。","乘輗轺兮驾蜚龙。","骖白鹿兮从仙僮。","游北岳兮与天通。","玄碑既立双阙建兮。","□□□□大路畔兮。","亭长阍□□捍难兮。","列种槐梓方茂烂兮。","天下远近□不见兮。","公神日著声洞遍兮。","□□乾川传亿万兮。"]},{"t":"李翊夫人碑叹","f":"楚辞体","c":["阴阳分兮钟律滋。","星月列兮有四时。","神宓设兮万姓熹。","寿十二兮九九期。","五三末兮衰在姬。","秋发兮春华殆。","周公九兮成称灾。","靡黄发兮盖夭胎。","卅有皇兮气所裁。","赴鸿渊兮逝不来。","凤延颈兮泣交颐。","■■悲兮涕陨零。","寐耿耿兮摧伤情。","彼苍天兮朔神灵。","忡切剥兮年法荣。","兰茝亡兮丧芝英。","谁不忉兮作偯声。","畴■号兮鸣莺莺。","杞之至兮感动城。","陟四极兮升天庭。","曰司命兮致不平。","飞蜂?兮豁仁良。","魂魄孤兮独茕茕。","陈衤勺祠兮返所生。","幽不见兮存厥井刂。","嗟日遐兮适窅窅。"]},{"t":"郭辅碑歌","f":"古风","c":["寔惟先生，虢仲之裔。","盛德遗祀，休矣亦世。","孝友贞信，仁恕好惠。","直己自求，不欲荣势。","绰绰令人，获道之至。","笃生七子，钟天之祉。","堂堂四俊，硕大婉敏。","娥娥三妃，行追大姒。","叶叶昆嗣，福禄茂止。","克昌厥后，身去烈在。","镌石作歌，昭示万祀。"]},{"t":"风雨诗","f":"楚辞体","c":["日不显目兮黑云多。","月不见视兮风非沙。","从恣蒙水诚江河。","州流灌注兮转扬波。","辟柱槙到忘相加。","天门狭小路彭池。","无因以上如之何。","兴诗教海兮诚难过。"]},{"t":"古诗十九首 其一","f":"五言古诗","c":["行行重行行，与君生别离。","相去万馀里，各在天一涯。","道路阻且长，会面安可知。","胡马依北风，越鸟巢南枝。","相去日已远，衣带日已缓。","浮云蔽白日，游子不顾返。","思君令人老，岁月忽已晚。","弃捐勿复道，努力加餐饭。"]},{"t":"古诗五首 其三","f":"五言古诗","c":["悲与亲友别，气结不能言。","赠子以自爱，道远会见难。","人生无几时，颠沛在其间。","念子弃我去，新心有所欢。","结志青云上，何时复来还。"]},{"t":"李陵录别诗二十一首 其二","f":"五言古诗","c":["携手上河梁，游子暮何之。","徘徊蹊路侧，悢悢不能辞。","行人难久留，各言长相思。","安知非日月，弦望自有时。","努力崇明德，皓首以为期。"]},{"t":"李陵录别诗二十一首 其三","f":"五言古诗","c":["嘉会难再遇，三载为千秋。","临河濯长缨，念子怅悠悠。","远望悲风至，对酒不能酬。","行人怀往路，何以慰我愁。","独有盈觞酒，与子结绸缪。"]},{"t":"李陵录别诗二十一首 其五","f":"五言古诗","c":["结发为夫妻，恩爱两不疑。","欢娱在今夕，燕婉及良时。","征夫怀往路，起视夜何其。","参辰皆已没，去去从此辞。","行役在战场，相见未有期。","握手一长叹，泪为生别滋。","努力爱春华，莫忘欢乐时。","生当复来归，死当长相思。"]},{"t":"李陵录别诗二十一首 其六","f":"五言古诗","c":["黄鹄一远别，千里顾徘徊。","胡马失其群，思心常依依。","何况双飞龙，羽翼临当乖。","幸有弦歌曲，可以喻中怀。","请为游子吟，泠泠一何悲。","丝竹厉清声，慷慨有馀哀。","长歌正激烈，中心怆以摧。","欲展清商曲，念子不得归。","俯仰内伤心，泪下不可挥。","愿为双黄鹄，送子俱远飞。"]},{"t":"李陵录别诗二十一首 其七","f":"五言古诗","c":["烛烛晨明月，馥馥我兰芳。","芬馨良夜发，随风闻我堂。","征夫怀远路，游子恋故乡。","寒冬十二月，晨起践严霜。","俯观江汉流，仰视浮云翔。","良友远别离，各在天一方。","山海隔中州，相去悠且长。","嘉会难再遇，欢乐殊未央。","愿君崇令德，随时爱景光。"]},{"t":"李陵录别诗二十一首 其九","f":"五言古诗","c":["烁烁三星列，拳拳月初生。","寒凉应节至，蟠蟀夜悲鸣。","晨风动乔木，枝叶日夜零。","游子暮思归，塞耳不能听。","远望正萧条，百里无人声。","豺狼鸣后园，虎豹步前庭。","远处天一隅，苦困独零丁。","亲人随风散，历历如流星。","三萍离不结，思心独屏营。","愿得萱草枝，以解饥渴情。"]},{"t":"李陵录别诗二十一首 其十","f":"五言古诗","c":["寂寂君子坐，奕奕合众芳。","温声何穆穆，因风动馨香。","清言振东序，良时著西痒。","乃令丝竹音，列席无高唱。","悲意何慷慨，清歌正激扬。","长哀发华屋，四坐莫不伤。"]},{"t":"李陵录别诗二十一首 其十一","f":"五言古诗","c":["晨风鸣北林，熠耀东南飞。","愿言所相思，日暮不垂帷。","明月照高楼，想见馀光辉。","玄鸟夜过庭，仿佛能复飞。","褰裳路踟蹰，彷徨不能归。","浮云日千里，安知我心悲。","思得琼树枝，以解长渴饥。"]},{"t":"李陵录别诗二十一首 其十二","f":"五言古诗","c":["陟彼南山隅，送子淇水阳。","尔行西南游，我独东北翔。","辕马顾悲鸣，五步一彷徨。","双凫相背飞，相远日已长。","远望云中路，想见来圭璋。","万里遥相思，何益心独伤。","随时爱景曜，愿言莫相忘。"]},{"t":"李陵录别诗二十一首 其十三","f":"五言古诗","c":["钟子歌南音，仲尼叹归与。","戎马悲边鸣，游子恋故庐。","阳鸟归飞云，蛟龙乐潜居。","人生一世间，贵与愿同俱。","身无四凶罪，何为天一隅。","与其苦筋力，必欲荣薄躯。","不如及清时，策名于天衢。"]},{"t":"李陵录别诗二十一首 其十四","f":"五言绝句","c":["凤皇鸣高冈，有翼不好飞。","安知凤皇德，贵其来见稀。"]},{"t":"李陵录别诗二十一首 其十五","f":"五言古诗","c":["红尘蔽天地，白日何冥冥。"]},{"t":"李陵录别诗二十一首 其十六","f":"五言古诗","c":["许由不洗耳。","后世有何徵。"]},{"t":"李陵录别诗二十一首 其十七","f":"五言古诗","c":["童童孤生柳，寄根河水泥。","连翩游客子，于冬服凉衣。","去家千里馀，一身常渴饥。","寒夜立清庭，仰瞻天汉湄。","寒风吹我骨，严霜切我肌。","忧心常惨戚，晨风为我悲。","瑶光游何速，行愿去何迟。","仰视云间星，所若割长帷。","低头还自怜，盛年行已衰。","依依恋明世，怆怆难久怀。"]},{"t":"李陵录别诗二十一首 其十八","f":"五言古诗","c":["双凫俱北飞，一凫独南翔。","子当留斯馆，我当归故乡。","一别如秦胡，会见何讵央。","怆悢切中怀，不觉泪沾裳。","愿子长努力，言笑莫相忘。"]},{"t":"李陵录别诗二十一首 其十九","f":"五言律诗","c":["清凉伊夜没，微风动单帱。","招摇西北驰，天汉东南流。","严父潜长夜，慈母去中堂。","行行且自割，无令五内伤。"]},{"t":"古诗二首 其一","f":"五言绝句","c":["采葵莫伤根，伤根葵不生。","结交莫羞贫，羞贫友不成。"]},{"t":"古诗二首 其二","f":"五言绝句","c":["甘瓜抱苦蒂，美枣生荆棘。","利傍有倚刀，贪人还自贼。"]},{"t":"古诗一首","f":"五言古诗","c":["青青陵中草，倾叶晞朝日。","阳春布惠泽，枝叶可缆结。","草木为恩感，况人含气血。"]},{"t":"古五杂俎诗","f":"古风","c":["五杂俎，冈头草。","往复还，车马道。","不获已，人将老。"]},{"t":"古两头纤纤诗","f":"古风","c":["两头纤纤月初生。","半白半黑。","眼中睛。","腷腷膊々鸡初鸣。","磊磊落落向曙星。"]},{"t":"古诗 其一","f":"古风","c":["啼呼哭泣，如吹胡笳。"]},{"t":"古诗 其二","f":"五言古诗","c":["有客从南来，赠我一抱笔。"]},{"t":"古诗 其四","f":"五言古诗","c":["离家千里客，戚戚多思复。"]},{"t":"古诗 其五","f":"五言古诗","c":["日暮途且远，游子悲故乡。"]},{"t":"古诗 其六","f":"五言古诗","c":["屡见流芳歇。"]},{"t":"古诗 其七","f":"五言古诗","c":["石门通越井。"]},{"t":"古游仙诗","f":"古风","c":["带我琼瑶佩，飧我沆?浆。"]},{"t":"陇头歌","f":"古风","c":["陇头流水，流离四下。","念我行役，飘然旷野。","登高望远，涕零双堕。"]},{"t":"陇头歌","f":"古风","c":["陇头流水，鸣声幽咽。","遥望秦川，肝肠断绝。"]},{"t":"邺人金凤旧歌","f":"七言古诗","c":["凤阳门南天一半。","上有金凤相飞唤。","欲去不去著锁绊。"]},{"t":"徐干引古人歌","f":"古风","c":["相彼玄鸟，止于陵阪。","仁道在近，求之无远。"]},{"t":"徐州为王祥歌","f":"古风","c":["海沂之康，实赖王祥。","邦国不空，别驾之功。"]},{"t":"荥阳令歌","f":"古风","c":["荥阳令。","有异政。","修立学校人易性。","令我子弟耻斗讼。"]},{"t":"襄阳民为胡烈歌 其一","f":"古风","c":["美哉明后，俊哲惟嶷。","陶广乾坤，周孔是则。","文武播畅，威振遐域。"]},{"t":"襄阳民为胡烈歌 其二","f":"古风","c":["譬春之阳，如冬之日。","耕者让畔，百姓丰溢。","惟我胡父，恩惠难置。"]},{"t":"行者歌","f":"七言绝句","c":["青槐夹道多尘埃。","龙楼凤阙望崔嵬。","清风细雨杂香来。","土上出金火照台。"]},{"t":"太和中京师歌","f":"五言古诗","c":["其奈汝曹何。"]},{"t":"明帝时宫人谣","f":"五言绝句","c":["不服辟寒金，那得帝王心。","不服辟寒钿，那得帝王怜。"]},{"t":"明帝景初中童谣","f":"七言古诗","c":["阿公阿公驾马车。","不意阿公东渡河。","阿公东还当奈何。"]},{"t":"正始中时人谣","f":"古风","c":["何邓丁。","乱京城。"]},{"t":"嘉平中谣","f":"七言古诗","c":["白马素羁西南驰。","其谁乘者朱虎骑。"]},{"t":"蒋济为护军时谣言","f":"古风","c":["欲求牙门。","当得千匹。","百人督。","五百匹。"]},{"t":"曹操引谚","f":"古风","c":["失晨之鸡，思补更鸣。"]},{"t":"曹操引里谚","f":"古风","c":["让礼一寸，得礼一尺。"]},{"t":"曹丕引里语","f":"古风","c":["家有敝帚，享之千金。"]},{"t":"曹丕引里语","f":"古风","c":["汝无自誉。","观汝作家书。"]},{"t":"曹植引谚","f":"古风","c":["相门有相。","将门有将。"]},{"t":"徐干引古语","f":"古风","c":["至德之贵，何往不遂。","至德之荣，何往不成。"]},{"t":"陈琳引谚","f":"古风","c":["掩目捕雀。"]},{"t":"王昶引谚","f":"古风","c":["救寒莫如重裘。","止谤莫如自修。"]},{"t":"王昶引语","f":"古风","c":["如不知足。","则失所欲。"]},{"t":"鱼豢引谚","f":"古风","c":["贫不学俭，卑不学恭。"]},{"t":"沮授引语","f":"古风","c":["一兔走衢，万人逐之。","一人获之，贪者悉止。"]},{"t":"曹囧引语","f":"古风","c":["百足之虫，至死不僵。"]},{"t":"林恕引谚","f":"古风","c":["使口如鼻，至老不失。"]},{"t":"军中为典韦语","f":"七言古诗","c":["帐下壮士有典君。","手把双戟八十斤。"]},{"t":"军中为夏侯渊语","f":"古风","c":["典军校尉夏侯渊。","三日五百。","六日一千。"]},{"t":"军中为徐晃语","f":"古风","c":["不得饷。","属徐晃。"]},{"t":"军中为卢洪赵达语","f":"古风","c":["不畏曹公，但畏卢洪。","卢洪尚可，赵达杀我。"]},{"t":"鸿胪中为韩暨韩宣语","f":"古风","c":["大鸿胪。","小鸿胪。","前后治行相曷如。"]},{"t":"时人为曹洪骏马谚","f":"古风","c":["凭空虚跃。","曹家白鹤。"]},{"t":"众人为贾洪严危语","f":"七言古诗","c":["州中晔晔贾叔业，辨论汹汹严文通。"]},{"t":"时人称邢颙语","f":"七言古诗","c":["德行堂堂邢子昂。"]},{"t":"京师为邓飏语","f":"七言古诗","c":["以官易富邓玄茂。"]},{"t":"时人为李丰等谤语","f":"七言古诗","c":["曹爽之势热如汤。","太傅父子冷如浆。","李丰兄弟如游光。"]},{"t":"时人为何晏邓飏丁谧曹爽谤语","f":"古风","c":["台中有三狗。","二狗崖柴不可当。","一狗凭默作疸囊。"]},{"t":"时人为陈群陈泰语","f":"古风","c":["公惭卿，卿惭长。"]},{"t":"博昌人为蒋任二姓语","f":"古风","c":["蒋氏翁。","任氏童。"]},{"t":"时人为杨阿若号","f":"七言古诗","c":["东市相斫杨阿若。","西市相斫杨阿若。"]},{"t":"时人为张氏兄弟语","f":"古风","c":["张氏十龙。","儒雅温恭。"]},{"t":"魏鼓吹曲十二曲 其一 楚之平","f":"古风","c":["楚之平，义兵征。","神武奋，金鼓鸣。","迈武德，扬洪名。","汉室微，社稷倾。","皇道失，桓与灵。","阉宦炽，群雄争。","边韩起，乱金城。","中国扰，无纪经。","赫武皇，起旗旌。","麾天下，天下平。","济九州，九州宁。","创武功，武功成。","越五帝，邈三王。","兴礼乐，定纪纲。","普日月，齐辉光。"]},{"t":"魏鼓吹曲十二曲 其二 战荥阳","f":"古风","c":["战荥阳。","汴水陂。","戎士愤怒。","贯甲驰。","陈未成。","退徐荥。","二万骑。","堑垒平。","戎马伤。","六军惊。","势不集。","众几倾。","白日没。","时晦冥。","顾中牟。","心屏营。","同盟疑。","计无成。","赖我武皇万国宁。"]},{"t":"魏鼓吹曲十二曲 其三 获吕布","f":"古风","c":["获吕布。","戮陈宫。","芟夷鲸鲵。","驱骋群雄。","囊括天下运掌中。"]},{"t":"魏鼓吹曲十二曲 其四 克官渡","f":"古风","c":["克绍官渡由白马。","僵尸流血被原野。","贼众如犬羊。","王师尚寡沙堆傍。","风飞扬。","转战不利士卒伤。","今日不胜后何望。","土山地道不可当。","卒胜大捷震冀方。","屠城破邑。","神武遂章。"]},{"t":"魏鼓吹曲十二曲 其五 旧邦","f":"七言古诗","c":["旧邦萧条心伤悲。","孤魂翩翩当何依。","游士恋故涕如摧。","兵起事大令愿违。","传求亲戚在者谁。","立庙置后魂来归。"]},{"t":"魏鼓吹曲十二曲 其六 定武功","f":"古风","c":["定武功。","济黄河。","河水汤汤。","旦暮有横流波。","袁氏欲衰。","兄弟寻干戈。","决漳水。","水流滂沱。","嗟城中如流鱼。","谁能复顾室家。","计穷虑尽求来连和。","和不时心中忧戚。","贼众内溃。","君臣奔北。","拔邺城奄有魏国。","王业艰难。","览观古今。","可为长叹。"]},{"t":"魏鼓吹曲十二曲 其七 屠柳城","f":"古风","c":["屠柳城。","功诚难。","越度陇塞路漫漫。","北逾冈平。","但闻悲风正酸。","蹋顿授首。","遂登白狼山。","神武慹海外。","永无北顾患。"]},{"t":"魏鼓吹曲十二曲 其八 平南荆","f":"古风","c":["南荆何辽辽。","江汉浊不清。","菁茅久不贡。","王师赫南征。","刘琮据襄阳。","贼备屯樊城。","六军庐新野。","金鼓震天庭。","刘子面缚至。","武皇许其成。","许与其成抚其民。","陶陶江汉间。","普为大魏臣。","大魏臣。","向风思自新。","思自新。","齐功古人。","在昔虞与唐。","大魏得与均。","多选忠义士。","为喉唇。","天下一定。","万世无风尘。"]},{"t":"魏鼓吹曲十二曲 其九 平关中","f":"古风","c":["平关中，路向潼。","济浊水，立高墉。","斗韩马，离群凶。","选骁骑，纵两翼。","虏崩溃，级万亿。"]},{"t":"魏鼓吹曲十二曲 其十 应帝期","f":"古风","c":["应帝期。","于昭我文皇。","历数承天序。","龙飞自许昌。","聪明昭四表。","恩德动遐方。","星辰为垂耀。","日月为重光。","河洛吐符瑞。","草木挺嘉祥。","麒麟步郊野。","黄龙游津梁。","白虎依山林。","凤凰鸣高冈。","考图定篇籍。","功配上古羲皇。","羲皇无遗文。","仁圣相因循。","期运三千岁。","一生圣明君。","尧授舜万国。","万国皆附亲。","四门为穆穆。","教化常如神。","大魏兴盛。","与之为邻。"]},{"t":"魏鼓吹曲十二曲 其十一 邕熙","f":"古风","c":["邕熙。","君臣念德。","天下治。","登帝道。","获瑞宝。","颂声并作。","洋洋浩浩。","吉日临高堂。","置酒列名倡。","歌声一何纡馀。","杂笙簧。","八音谐。","有纪纲。","子孙永建万国。","寿考乐无央。"]},{"t":"魏鼓吹曲十二曲 其十二 太和","f":"古风","c":["惟太和元年。","皇帝践阼。","圣且仁。","德泽为流布。","灾蝗一时为绝息。","上天时雨露。","五谷滋田畴。","四民相率遵轨度。","事务澄清。","天下狱讼察以情。","元首明。","魏家如此。","那得不太平。"]},{"t":"时人为张飞玉追马歌","f":"五言古诗","c":["人守有张飞。","马中有玉追。"]},{"t":"襄阳乡里为诸葛亮谚","f":"古风","c":["莫作孔明择妇。","止得阿承丑女。"]},{"t":"襄阳乡里为马良谚","f":"古风","c":["马氏五常。","白眉最良。"]},{"t":"乡里为李严谚","f":"古风","c":["难可狎。","李鳞甲。"]},{"t":"谯周引谚","f":"古风","c":["射幸数跌。","不如审发。"]},{"t":"时人语","f":"古风","c":["前有何句。","后有张廖。"]},{"t":"百姓谚","f":"七言古诗","c":["死诸葛走生仲达。"]},{"t":"时人为刘巴语","f":"五言古诗","c":["生居三湘头，死葬三湘尾。"]},{"t":"诸葛亮引语论光武","f":"七言古诗","c":["曲突徙薪为彼人，焦头烂额为上客。"]},{"t":"吴歌曲","f":"古风","c":["仙人赍持何等。","前谒海童。"]},{"t":"时人为周瑜谣","f":"古风","c":["曲有误。","周郎顾。"]},{"t":"黄龙中童谣","f":"古风","c":["行白者君。","追汝句骊马。"]},{"t":"孙亮初童谣","f":"古风","c":["吁汝恪。","何若若。","芦苇单衣篾钩络。","于何相求杨子阁。"]},{"t":"孙亮初白鼍鸣童谣","f":"古风","c":["白鼍鸣。","龟背平。","南郡城中可长生。","守死不去义无成。"]},{"t":"建衡中寿春童谣","f":"古风","c":["吴天子，当西上。"]},{"t":"使者为妖祠诗诗","f":"古风","c":["楚九州渚。","吴九州都。","扬州士。","作天子。","四世治。","太平始。"]},{"t":"孙皓天纪中童谣","f":"五言绝句","c":["阿童复阿童，衔刀游渡江。","不畏岸上虎，独畏水中童。"]},{"t":"广陵谚","f":"古风","c":["解结理烦。","我国陆君。"]},{"t":"时人语","f":"古风","c":["支郎。","眼中黄。","形躯虽细是智囊。"]},{"t":"黄武中产儿语","f":"古风","c":["天方明，河欲清。","鼎折脚，金乃生。"]},{"t":"时人为殷礼语","f":"七言古诗","c":["奇才强记殷往嗣。"]},{"t":"永安中南郡儿语","f":"古风","c":["三公锄。","司马如。"]},{"t":"诸葛恪引里语","f":"古风","c":["明镜所以照形，古事所以知今。"]},{"t":"沈莹引谚","f":"古风","c":["宁负千石之粟。","不愿负人猴头羹。","宁去累世田宅。","不去䱥鱼额。"]},{"t":"杨桃谚","f":"古风","c":["杨桃无蹙，一岁二熟。"]},{"t":"吴鼓吹曲十二曲 其一 炎精缺","f":"古风","c":["炎精缺，汉道微。","皇纲弛，政德违。","众奸炽，民冈依。","赫武烈，越龙飞。","陟天衢，耀灵威。","鸣雷鼓，抗电麾。","抚乾衡，镇地机。","厉虎旅，骋熊罴。","发神听，吐英奇。","张角破，边韩羁。","宛颍平，南土绥。","神武章，渥泽施。","金声震，仁风驰。","显高门，启皇基。","统冈极，垂将来。"]},{"t":"吴鼓吹曲十二曲 其二 汉之季","f":"古风","c":["汉之季。","董卓乱。","桓桓武烈应时运。","义兵兴。","云旗建。","厉六师。","罗八阵。","飞鸣镝。","接白刃。","轻骑发。","介士奋。","丑虏震。","使众散。","劫汉主。","迁西馆。","雄豪怒。","元恶偾。","赫赫皇祖功名闻。"]},{"t":"吴鼓吹曲十二曲 其三 摅武师","f":"古风","c":["摅武师。","斩黄祖。","攘夷凶族。","革平西夏。","炎炎大烈震天下。"]},{"t":"吴鼓吹曲十二曲 其四 伐乌林","f":"古风","c":["曹操北伐拔柳城。","乘胜席卷遂南征。","刘氏不睦。","八郡震惊。","众既降。","操屠荆。","舟车十万扬风声。","议者狐疑虑无成。","赖我大皇发圣明。","虎臣雄烈周与程。","破操乌林。","显章功名。"]},{"t":"吴鼓吹曲十二曲 其五 秋风","f":"古风","c":["秋风扬沙尘。","寒露沾衣裳。","角弓持弦急。","鸠鸟化为鹰。","边垂飞羽檄。","寇贼侵界疆。","跨马披介胄。","慷慨怀悲伤。","辞亲向长路。","安知存与亡。","穷达固有分。","志士思立功。","思立功。","邀之战场。","身逸获高赏。","身没有遗封。"]},{"t":"吴鼓吹曲十二曲 其六 克皖城","f":"七言古诗","c":["克灭皖城遏寇贼，恶此凶孽阻奸慝。","王师赫征众倾覆，除秽去暴戢兵革。","民得就农边境息，诛君吊民昭至德。"]},{"t":"吴鼓吹曲十二曲 其七 关背德","f":"古风","c":["关背德。","作鸱张。","割我邑城图不祥。","称兵北伐围樊阳。","嗟臂大于股。","将受其殃。","巍巍夫圣主。","睿德与玄通。","与玄通。","亲任吕蒙。","泛舟洪汜池。","溯涉长江。","神武一何桓桓。","声烈正与风翔。","历抚江安城。","大据郢邦。","虏羽授首。","百蛮咸来同。","盛哉三比隆。"]},{"t":"吴鼓吹曲十二曲 其八 通荆门","f":"古风","c":["荆门限巫山。","高峻与云连。","蛮夷阻其险。","历世怀不宾。","汉王据蜀郡。","崇好结和亲。","乖微中情疑。","谗夫乱其间。","大皇赫斯怒。","虎臣勇气震。","荡涤幽薮讨不恭。","观兵扬炎耀。","厉锋整封疆。","整封疆。","阐扬威武容。","功赫戏。","洪烈炳章。","邈矣帝皇世。","圣吴同厥风。","荒裔望清化。","化恢弘。","煌煌大吴。","延祚永未央。"]},{"t":"吴鼓吹曲十二曲 其九 章洪德","f":"古风","c":["章洪德。","迈威神。","感殊风。","怀远邻。","平南裔。","齐海滨。","越裳贡。","扶南臣。","珍货充庭。","所见日新。"]},{"t":"吴鼓吹曲十二曲 其十 从历数","f":"古风","c":["从历数。","于穆我皇帝。","圣哲受之天。","神明表奇异。","建号创皇基。","聪睿协神思。","德泽浸及昆虫。","浩荡越前代。","三光显精耀。","阴阳称至治。","肉角步郊畛。","凤凰栖灵囿。","神龟游沼池。","图谶摹文字。","黄龙觌鳞。","符祥日月记。","览往以察今。","我皇多哙事。","上钦昊天象。","下副万姓意。","光被弥苍生。","家户蒙惠赍。","风教肃以平。","颂声章嘉喜。","大吴兴隆。","绰有馀裕。"]},{"t":"吴鼓吹曲十二曲 其十一 承天命","f":"古风","c":["承天命。","于昭圣德。","三精垂象。","符灵表德。","巨石立。","九穗植。","龙金其麟。","乌赤其色。","舆人歌。","亿夫叹息。","超龙升。","袭帝服。","穷淳懿。","体玄嘿。","夙兴临朝。","劳谦日昃。","易简以崇仁。","放远谗与慝。","举贤才。","亲近有德。","均田畴。","茂稼穑。","审法令。","定品式。","考功能。","明黜陟。","人思自尽。","唯心与力。","家国治。","王道直。","思我帝皇。","寿万亿。","长保天禄。","祚无极。"]},{"t":"吴鼓吹曲十二曲 其十二 玄化","f":"古风","c":["玄化象以天。","陛下圣真。","张皇纲。","率道以安民。","惠泽宣流而云布。","上下睦亲。","君臣酣宴乐。","激发弦歌扬妙新。","修文筹庙胜。","须时备驾巡洛津。","康哉泰。","四海欢忻。","越与三五邻。"]},{"t":"会稽民为徐弘歌","f":"古风","c":["徐圣通，政无双。","平刑罚，奸宄空。"]},{"t":"南土为杜预歌","f":"七言古诗","c":["后世无叛由杜翁。","孰识智名与勇功。"]},{"t":"阳平人为束皙歌","f":"古风","c":["束先生。","通神明。","请天三日甘雨零。","我黍以育。","我稷以生。","何以畴之。","报束长生。"]},{"t":"三郡民为应詹歌","f":"古风","c":["乱离既普，殆为灰朽。","侥幸之运，赖兹应后。","岁寒不凋，孤境独守。","拯我涂炭，惠隆丘阜。","润同江海，恩犹父母。"]},{"t":"襄阳儿童为山简歌","f":"五言律诗","c":["山公出何许，往至高阳池。","日夕倒载归，酩酊无所知。","时时能骑马，倒着白接䍦。","举鞭向葛强，何如并州儿。"]},{"t":"吴郡民为邓攸歌","f":"五言绝句","c":["紞如打五鼓，鸡鸣天欲曙。","邓侯挽不留，谢令推不去。"]},{"t":"豫州耆老为祖逖歌","f":"七言绝句","c":["幸哉遗黎免俘虏。","三辰既朗遇慈父。","玄酒忘劳甘瓠脯。","何以咏思歌且舞。"]},{"t":"时人为阮修歌","f":"五言绝句","c":["长安教书罢，洛阳卖卜来。","百钱系杖头，能使世人解。"]},{"t":"吏为郭颐刘聪歌","f":"古风","c":["我有贤后。","能任玄明。","政理人殷。"]},{"t":"京师为张轨歌","f":"古风","c":["凉州大马。","横行天下。","凉州鸱苕寇贼消。","鸱苕翩翩怖杀人。"]},{"t":"陇上为陈安歌","f":"七言古诗","c":["陇上壮士有陈安，躯干虽小腹中宽。","爱养将士同心肝，䯀骢父马铁锻鞍。","七尺大刀奋如湍，丈八蛇矛左右盘。","十荡十决无当前，战如三交失蛇矛。","弃我䯀骢窜岩幽，为我外援而悬头。","西流之水东流河，一去不还奈子何。"]},{"t":"泰始中谣","f":"古风","c":["贾裴王，乱纪纲。","王裴贾，济天下。"]},{"t":"泰始中童谣","f":"七言古诗","c":["宫中大马几作驴。","大石压之不得舒。"]},{"t":"军中谣","f":"古风","c":["以计代战。","一当万。"]},{"t":"蜀民为许逊谣","f":"古风","c":["人无盗窃，吏无奸欺。","我君活人，病无能为。"]},{"t":"武帝太康后童谣三首 其一","f":"古风","c":["局缩肉。","数横目。","中国当败吴当复。"]},{"t":"武帝太康后童谣三首 其二","f":"古风","c":["宫门柱。","且莫朽。","吴当复在三十年后。"]},{"t":"武帝太康后童谣三首 其三","f":"五言古诗","c":["鸡鸣不拊翼。","吴复不用力。"]},{"t":"蜀人谣二首 其一","f":"古风","c":["尚之所爱，非邪则佞。","尚之所憎，非忠则正。","富拟鲁卫，家成市里。","贪如豺狼，无复极已。"]},{"t":"蜀人谣二首 其二","f":"古风","c":["蜀贼尚可，罗尚杀我。","平西将军，反更为祸。"]},{"t":"惠帝即位时儿童谣","f":"古风","c":["两火没地，哀哉秋兰。","归形街邮，终为人叹。"]},{"t":"赵王伦为乱时谣","f":"古风","c":["金章满箱。","尚不可长。"]},{"t":"永熙中温县狂人书","f":"古风","c":["光光文长。","以戟为墙。","毒药虽行。","戟还自伤。"]},{"t":"惠帝永熙中童谣","f":"古风","c":["二月末。","三月初。","桑生襄蕃柳叶舒。","荆笔杨版行诏书。","宫中大马几作驴。"]},{"t":"元康三的蜀中童谣四首 其一","f":"古风","c":["郫城坚。","盎底穿。","郫城细子李持细。"]},{"t":"元康三的蜀中童谣四首 其二","f":"古风","c":["江桥头。","阙下市。","城都北门十八子。"]},{"t":"元康三的蜀中童谣四首 其三","f":"古风","c":["巴郡葛，当下美。"]},{"t":"元康三的蜀中童谣四首 其四","f":"古风","c":["有客有客。","来侵门陌。","其气欲索。"]},{"t":"元康中童谣","f":"古风","c":["屠苏鄣日覆两耳。","当见?儿作天子。"]},{"t":"元康中洛中童谣","f":"七言古诗","c":["虎从北来鼻头汗。","龙从南来登城看。","水从西来河灌灌。"]},{"t":"惠帝元康中京洛童谣二首 其一","f":"楚辞体","c":["南风起兮吹白沙。","遥望鲁国何嵯峨。","千岁髑髅生齿牙。"]},{"t":"惠帝元康中京洛童谣二首 其二","f":"七言古诗","c":["城东马子莫咙哅。","比至来年缠汝鬉。"]},{"t":"惠帝大安中童谣","f":"五言古诗","c":["五马浮渡江，一马化为龙。"]},{"t":"著布谣","f":"古风","c":["著布耙腹。","为齐持服。"]},{"t":"洛下谣","f":"七言古诗","c":["草木萌牙杀长沙。"]},{"t":"惠帝时洛阳童谣","f":"七言古诗","c":["邺中女子莫千妖。","前至三月抱胡腰。"]},{"t":"怀帝永嘉初童谣","f":"七言古诗","c":["洛中大鼠长尺二。","若不早去天狗至。"]},{"t":"苟晞将破汲桑诗谣","f":"七言古诗","c":["元超兄弟大洛度。","上桑打椹为苟作。"]},{"t":"军中为汲桑谣","f":"七言古诗","c":["士为将军何可羞。","六月重茵披衲裘。","不识寒暑断他头。","雄儿田兰为报仇。","中夜斩首谢并州。"]},{"t":"王彭祖谣","f":"七言古诗","c":["幽州城门似藏户。","中有伏尸王彭祖。"]},{"t":"北州为朱硕棘嵩谣","f":"七言古诗","c":["府中赫赫朱邱伯，十囊五囊入棘郎。"]},{"t":"悯帝初童谣","f":"古风","c":["天子何在。","豆田中。"]},{"t":"悯帝初童谣","f":"五言古诗","c":["天子在何许，近在豆田中。"]},{"t":"建兴中江南谣","f":"五言绝句","c":["訇如白坑破，合集持作甒。","扬州破换败，吴兴覆瓿甊。"]},{"t":"王敦将灭时童谣","f":"古风","c":["剪生剪韭。","断阳柳。","河东小子。","令我与子。"]},{"t":"明帝太宁初童谣","f":"古风","c":["恻力恻力。","放马山侧。","大马死。","小马饿。","高山崩。","石自破。"]},{"t":"永嘉中长安谣","f":"古风","c":["秦川中。","血没腕。","唯有凉州倚柱观。"]},{"t":"凉州民谣","f":"古风","c":["蛇利炮。","蛇利炮。","公头坠地而不觉。"]},{"t":"西土谣","f":"古风","c":["手莫头。","图凉州。"]},{"t":"姑臧谣","f":"七言古诗","c":["鸿从南来雀不惊。","谁谓孤雏尾翅生。","高举六翮凤凰鸣。"]},{"t":"时人为张冲谣","f":"古风","c":["推财不疑。","张长思。"]},{"t":"冀州童谣","f":"古风","c":["古在左，月在右。","让去言，或入口。"]},{"t":"临水人为张楼谣","f":"七言古诗","c":["阳平张楼头如箱。","见人切齿剧虎狼。"]},{"t":"南广郡行人语","f":"古风","c":["犹溪赤水，盘蛇七曲。","盘羊乌栊，气与天通。","看都护泚，伫柱呼伊。","庲降贾子，左檐七里。"]},{"t":"䱥鱼谚","f":"五言古诗","c":["宁去累世宅。","不去䱥鱼额。"]},{"t":"陆机引里语","f":"古风","c":["斫檀不谛。","得系迷。","系迷尚可。","得驳马。"]},{"t":"陆机引齐人谚","f":"古风","c":["上山斫檀。","挈榼先殚。"]},{"t":"陆机引里语","f":"古风","c":["黄栗留。","看我麦。","黄葚熟。"]},{"t":"陆机引辽东乡语","f":"古风","c":["居就粮。","梁水鲂。"]},{"t":"陆机引里语","f":"古风","c":["网鱼得鱮。","不如啖茹。"]},{"t":"陆机引里语","f":"古风","c":["趣织鸣。","懒妇惊。"]},{"t":"杨济引谚","f":"古风","c":["生子凝，了官事。"]},{"t":"成公绥引谚","f":"古风","c":["钱无耳。","何可訚使。"]},{"t":"鲁褒引谚","f":"古风","c":["钱无耳。","可使鬼。"]},{"t":"傅玄引谚","f":"五言绝句","c":["己是而彼非，不当与非争。","彼是而己非，不当与非平。"]},{"t":"驾循引谚","f":"古风","c":["射的白。","斛米百。","射的玄斛米千。"]},{"t":"陆士衡引俗语","f":"七言古诗","c":["金马门外聚群贤。","铜驼陌上集少年。"]},{"t":"杨泉引里语","f":"古风","c":["能理乱丝。","乃可读诗。"]},{"t":"杨泉引语","f":"古风","c":["黄金累千。","不如一贤。","土非玉璧。","谈者为价。","上不正。","下参差。"]},{"t":"卫展引谚","f":"古风","c":["廷尉狱，平如砥。","有钱生，无钱死。"]},{"t":"袁淮引谚","f":"古风","c":["岁在申酉，乞浆得酒。","岁在辰巳，嫁妻卖子。"]},{"t":"时人为崔洪语","f":"古风","c":["丛生棘刺，来自博陵。","在南为鹞，在北为鹰。"]},{"t":"时人为石苞语","f":"古风","c":["石仲容，姣无双。"]},{"t":"时人为羊祜语","f":"古风","c":["二王当国。","羊公无德。"]},{"t":"时人为杜预号","f":"古风","c":["杜武库言，无所不有。"]},{"t":"京师为刘舆刘琨语","f":"古风","c":["洛中奕奕。","庆孙越石。"]},{"t":"时人欧阳建语","f":"古风","c":["渤海赫赫。","欧阳坚石。"]},{"t":"时人为卫玠王澄语","f":"古风","c":["卫玠谈道。","平子绝倒。"]},{"t":"时人为乐广卫玠语","f":"古风","c":["妇翁冰清，女婿玉润。"]},{"t":"时人为二陆三张语","f":"古风","c":["二陆入洛，三张减价。"]},{"t":"蜀民为何随语","f":"古风","c":["安汉吏取粮。","令为之偿。"]},{"t":"时人为裴秀语","f":"古风","c":["后进领袖。","有裴秀。"]},{"t":"时人为谢鲲语","f":"古风","c":["任达不已。","幼舆折齿。"]},{"t":"时人为刘颂语","f":"古风","c":["雷蒋谷鲁。","刘为最祖。"]},{"t":"世为卞氏语","f":"古风","c":["卞氏六龙，玄仁无双。"]},{"t":"襄阳里人为庞焕语","f":"古风","c":["我家池里，龙种来归。"]},{"t":"三魏为刘毅语","f":"五言古诗","c":["但闻刘轼曹，不闻杜府君。"]},{"t":"巴蜀为谯登文石张罗语","f":"五言绝句","c":["谯登治涪城，文石在巴西。","张罗守合水，巴氐那得前。"]},{"t":"洛中为刘氏兄弟语","f":"古风","c":["洛中雅雅。","有三嘏。"]},{"t":"洛中为荀闿语","f":"古风","c":["洛中英英。","荀道明。"]},{"t":"洛中为冯荪语","f":"古风","c":["洛中铮铮。","冯惠卿。"]},{"t":"时人为冯荪邢乔李顺语","f":"古风","c":["冯才清。","李才明。","纯粹邢。"]},{"t":"时人为江统语","f":"古风","c":["嶷然稀言。","江应元。"]},{"t":"时人为赵王伦谚","f":"古风","c":["貂不足。","狗尾续。"]},{"t":"成都王颖盛时里语","f":"古风","c":["三部司马阶下兵。","四部司马尚长明。","欲知太平须石鳖鸣。"]},{"t":"成都王颖盛时义募将士谣语","f":"古风","c":["大事解。","蚕欲遽。","请且归。","赴时务。","昔以义来。","今以义去。","若复有急更相语。"]},{"t":"时人为王氏语","f":"古风","c":["王与马。","共天下。"]},{"t":"时人为邓攸语","f":"古风","c":["天道无知。","使邓伯道无儿。"]},{"t":"樊氏陂谚","f":"古风","c":["陂汪汪。","下田良。","樊子失业庾公昌。"]},{"t":"陈武引里语","f":"古风","c":["都亭鼠。","数闻长者语。"]},{"t":"时人为权翼苻雅语","f":"五言古诗","c":["不为权翼富，宁作苻雅贫。"]},{"t":"石勒时谚","f":"古风","c":["一杯食。","有两匕。","石勒死。","人不知。"]},{"t":"三秦记引谚","f":"古风","c":["心无忧患，不经二旬。","心若忧患，远离三春。"]},{"t":"秦雍为辛氏语","f":"古风","c":["五龙一门。","金友玉昆。"]},{"t":"晋四厢乐歌三首 其一 正旦大会行礼歌","f":"古风","c":["天鉴有晋，世祚圣皇。","时齐七政，朝此万方。","钟鼓斯震，九宾备礼。","正位在朝，穆穆济济。","煌煌三辰，实丽于天。","君后是象，威仪孔虔。","率礼无愆，莫非迈德。","仪刑圣皇，万邦惟则。"]},{"t":"晋四厢乐歌三首 其二 上寿酒歌","f":"古风","c":["于赫明明，圣德龙兴。","三朝献酒，万寿是膺。","敷佑四方，如日之升。","自天降祚，元吉有徵。"]},{"t":"晋四厢乐歌三首 其三 食举东西厢歌","f":"古风","c":["天命大晋，载育群生。","于穆上德，随时化成。","自祖配命，皇皇后辟。","继天创业，宣文之绩。","不显宣文，先知稼穑。","克恭克俭，足教足食。","既教食之，弘济艰难。","上帝是佑，下民所安。","天佑圣皇，万邦来贺。","虽安勿安，乾乾匪暇。","乃正丘郊，乃定冢社。","廙廙作宗，光宅天下。","惟敬朝飨，爰奏食举。","尽礼供御，嘉乐有序。","树羽设业，笙镛以间。","琴瑟齐列，亦有篪埙。","喤喤鼓钟，枪枪磬管。","八音克谐，载夷载简。","既夷既简，共大不御。","风化潜兴，如云如雨。","如云之覆，如雨之润。","声教所暨，无思不顺。","教以化之，乐以和之。","和而养之，时惟邕熙。","礼慎其仪，乐节其声。","于铄皇繇，既和且平。"]},{"t":"晋四厢乐歌三首 其一 正旦大会行礼歌","f":"古风","c":["于皇元首，群生资始。","履端大享，敬御繁祉。","肆觐群后，爰及卿士。","钦顺则元，允也天子。","明明天子，临下有赫。","四表宅心，惠浃荒貊。","柔远能迩，孔淑不逆。","来格祁祁，邦家是若。","光光邦国，天笃其祜。","丕显哲命，顾柔三祖。","世德作求，奄有九土。","思我皇度，彝伦攸序。","惟祖惟宗，高朗缉熙。","对越在天，骏惠在兹。","聿求厥成，我皇崇之。","式固其犹，往敬用治。"]},{"t":"晋四厢乐歌三首 其二 王公上寿酒歌","f":"古风","c":["践元辰。","延显融。","献羽觞。","祈令终。","我皇寿而隆。","我皇茂而嵩。","本枝奋百世。","休祚钟圣躬。"]},{"t":"晋四厢乐歌三首 其三 食举乐东西厢歌","f":"古风","c":["煌煌七曜，重明交畅。","我有嘉宾，是应是贶。","邦政既图，接以大飨。","人之好我，式遵德让。","宾之初筵，蔼蔼济济。","既朝乃宴，以洽百礼。","颁以位叙，或廷或陛。","登傧台叟，亦有兄弟。","胥子陪寮，宪兹度楷。","观颐养正，降福孔偕。","昔我三后，大业是维。","今我圣皇，焜耀前晖。","奕世重规，明照九畿。","思辑用光，时罔有违。","陟禹之迹，莫不来威。","天被显禄，福履是绥。","赫矣太祖，克广明德。","廓开宇宙，正世立则。","变化不经，民无瑕慝。","创业垂统，兆我晋国。","列文伯考，时惟帝景。","夷险平乱，威而不猛。","御衡不迷，皇涂焕炳。","七德咸宣，其宁惟水。","猗欤盛欤，先皇圣文。","则天作孚，大哉为君。","慎徽五典，帝载是勤。","文武发挥，茂建嘉勋。","修已济治，民用宁殷。","怀远烛幽，玄教氛氲。","善世不伐，服事三分。","德博化隆，道冒无垠。","隆化洋洋，帝命溥将。","登我晋道，越惟圣皇。","龙飞革运，临焘八荒。","睿哲钦明，配踪虞唐。","封建厥福，骏发其祥。","三朝习吉，终然允臧。","其臧惟何，总彼万方。","元侯列辟，四狱蕃王。","时见世享，率兹有常。","旅揖在庭，嘉客在堂。","宋卫既臻，陈留山阳。","我有宾使，观国之光。","贡贤纳计，献璧奉璋。","保佑命之，申锡无疆。","振鹭于飞，鸿渐其翼。","京邑穆穆，四方是式。","无竞惟人，王纲允敕。","君子来朝，言观其极。","翼翼大君，民之攸暨。","信理天工，惠康不匮。","将远不仁，训以淳粹。","幽明有伦，俊乂在位。","九族既睦，庶邦顺比。","开元布宪，四海鳞萃。","协时正统，殊涂同致。","厚德载物，灵心隆贵。","敷奏谠言，纳以无讳。","树之典象，诲之义类。","上教如风，下应如卉。","一人有庆，群萌以遂。","我后宴喜，令问不坠。","既宴既喜，翕是万邦。","礼仪卒度，物有其容。","晰晰庭燎，喤喤鼓钟。","笙磬咏德，万舞象功。","八音克谐，俗易化从。","其和如乐，庶品时邕。","时邕斌斌，六合同尘。","往我祖宣，威静殊邻。","首定荆楚，遂平燕秦。","亹亹文皇，迈德流仁。","爰造草昧，应乾顺民。","灵瑞告符，休徵响震。","天地弗违，以和神人。","既戡庸蜀，吴会是宾。","肃慎率职，楛矢来陈。","韩濊进乐，均协清钧。","西旅献獒，扶南效珍。","蛮裔重译，玄齿文身。","我皇抚之，景命惟新。","愔愔嘉会，有闻无声。","清酤既奠，笾豆既馨。","礼充乐备，箫韶九成。","恺乐饮酒，酣而不盈。","率土欢豫，邦国以宁。","王猷允塞，万载无倾。"]},{"t":"晋四厢乐歌三首 其一 王公上寿诗","f":"古风","c":["称元庆。","奉圣觞。","后皇延遐祚。","安乐抚万方。"]},{"t":"晋四厢乐歌三首 其二 食举东西厢乐诗","f":"古风","c":["明明在上。","丕显厥繇。","翼翼三寿。","蕃后惟休。","群生渐德。","六合承流。","三正元辰。","朝庆鳞萃。","华夏奉职贡。","八荒觐殊类。","黻冕充广庭。","鸣玉盈朝位。","济济朝位。","言观其光。","仪序既以时。","礼文焕以彰。","思皇享多祜。","嘉乐永无央。","九宾在庭。","胪赞既通。","升瑞奠贽。","乃侯乃公。","穆穆天尊。","隆礼动容。","履端承元吉。","介福御万邦。","朝享。","上下咸雍。","崇多仪。","繁礼容。","舞盛德。","歌九功。","扬芳烈。","播休踪。","皇化洽。","洞幽明。","怀柔百神。","辑祥祯。","潜龙跃。","雕虎仁。","仪凤鸟。","届游麟。","枯蠹荣。","竭泉流。","菌芝茂。","枳棘柔。","和气应。","休徵弦。","协灵符。","彰帝期。","绥宇宙。","万国和。","昊天成命。","赍皇家。","赍皇家。","世资圣哲。","三后在天。","启鸿烈。","启鸿烈。","隆王基。","率土讴吟。","欣戴于时。","恒文象。","代气著期。","泰始开元。","龙升在位。","四隩同风。","燮宁殊类。","五韪来备。","嘉生以遂。","凝庶绩。","臻太康。","申繁祉。","胤无疆。","本枝百世。","继绪言不忘。","继绪不忘。","休有烈光。","永言配命。","惟晋之祥。","圣明统世。","笃皇仁。","广大配天地。","顺动若陶钧。","玄化参自然。","至德通神明。","清风畅八极。","流泽被无垠。","于皇时晋。","奕世齐圣。","惟天降嘏。","神祇保定。","弘济区夏。","允集大命。","有命既集。","光帝猷。","大明重曜。","鉴六幽。","声教洋溢。","惠滂流。","惠滂流。","移风俗。","多士盈朝。","贤俊比屋。","敦世心。","断凋反素朴。","反素朴。","怀庶方。","干戚舞阶庭。","疏狄悦遐荒。","扶南假重译。","肃慎袭衣裳。","云覆雨施。","德洽无疆。","旁作穆穆。","仁化翔。","朝元日。","宾王庭。","承宸极。","当盛明。","衍和光。","竭祗诚。","仰嘉惠。","怀德馨。","游淳风。","泳淑风。","泳淑清。","协忆兆。","同欢荣。","建皇极。","统天位。","运阴阳。","御六气。","殷群生。","成性类。","王道浃。","治功成。","人伦序。","俗化清。","虔明祀。","祗三灵。","崇礼乐。","式仪刑。","庆元吉。","宴三朝。","播金石。","咏冷箫。","奏九夏。","舞云韶。","迈德音。","流英声。","八纮一。","六合宁。","六合宁。","承圣明。","王泽洽。","道登隆。","绥函夏。","总华戎。","齐德教。","混殊风。","混殊风。","康万国。","崇夷简。","尚敦德。","弘王度。","远遐则。"]},{"t":"晋四厢乐歌三首 其三 正旦大会行礼诗","f":"古风","c":["于赫皇祖。","迪哲齐圣。","经纬大业。","基天之命。","克开洪绪。","诞笃天庆。","旁济彝伦。","仰齐七政。","烈烈景皇。","克明克聪。","静封略。","定勋功。","成民立政。","仪刑万邦。","式固崇轨。","光绍前踪。","允文烈考。","睿哲应期。","参德天地。","比功四时。","大亨以正。","庶绩咸熙。","肇启晋宇。","遂登皇基。","明明我后。","玄德通神。","受终正位。","协应天人。","容民厚下。","育物流仁。","跻我王道。","辉光日新。"]},{"t":"晋宣文舞歌二首 其一 羽籥舞歌","f":"古风","c":["羲皇之初。","天地开元。","罔罟禽兽。","群黎以安。","神农教耕。","创业诚难。","民得粒食。","澹然无所患。","黄帝始征伐。","万品造其端。","军驾无常居。","是曰轩辕。","轩辕既勤止。","尧舜匪荒宁。","夏禹治水。","汤武又用兵。","孰能保安逸。","坐致太平。","圣皇迈乾乾。","天下兴颂声。","穆穆且明明。","惟圣皇。","道化彰。","溅四海。","清三光。","万几理。","庶事康。","潜龙升。","仪凤翔。","风雨时。","物繁昌。","却走马。","降瑞祥。","扬侧陋。","简忠良。","百禄是荷。","眉寿无疆。"]},{"t":"晋宣文舞歌二首 其二 羽铎舞歌","f":"古风","c":["昔在浑成时。","两仪尚未分。","阳升垂清景。","阴阴兴浮云。","中和合氛氲。","万物各异群。","人伦得其序。","众生乐圣君。","三统继五行。","然后有质文。","皇王殊运代。","治乱亦缤纷。","伊大晋。","德兼往古。","越牺农。","邈舜禹。","参天地。","陵三五。","礼唐周。","乐韶武。","岂惟箫韶。","六代具举。","泽沾地境。","化充天寓。","圣明临朝。","元凯作辅。","普天同乐胥。","浩浩元气。","遐哉太清。","五行流迈。","日月代征。","随时变化。","庶物乃成。","圣皇继天。","光济群生。","化之以道。","万国咸宁。","受兹介福。","延于亿龄。"]},{"t":"晋鼙舞歌五首 其一 洪业篇","f":"古风","c":["宣文创洪业。","盛德在泰始。","圣皇应灵符。","受命君四海。","万国何所乐。","上有明天子。","唐尧禅帝位。","虞舜惟恭己。","恭己正南面。","道化与时移。","大赦荡萌渐。","文教被黄支。","象天则地。","体无为。","聪明配日月。","神圣参两仪。","虽有三凶类。","静言无所施。","象天则地。","体无为。","稷契并佐命。","伊吕升王臣。","兰芷登朝肆。","下无失宿民。","声发响自应。","表立景来附。","虓虎从。","羁制。","潜龙升天路。","备物立成器。","变通极其数。","百事以时叙。","万机有常度。","训之以克让。","纳之以忠恕。","群下仰清风。","海外同欢慕。","象天则地。","化云布。","昔日贵雕饰。","今尚俭与素。","昔日多纤介。","今去情与故。","象天则地。","化云布。","济济大朝士。","夙夜综万机。","万机无废理。","明明降畴询问。","臣譬列星景。","君配朝日晖。","事业并通济。","功烈何巍巍。","五帝继三皇。","三王世所归。","圣德应期运。","天地不能违。","仰之弥已高。","犹天不可阶。","将复御龙氏。","凤皇在庭栖。"]},{"t":"晋鼙舞歌五首 其二 天命篇","f":"五言古诗","c":["圣祖受天命，应期辅魏皇。","入则综万机，出则征四方。","朝廷无遗理，方表宁且康。","道隆舜臣尧，积德逾大王。","孟度阻穷险，造乱天一隅。","神兵出不意，奉命致天诛。","赦善戮有罪，元恶宗为虚。","威风振劲蜀，武烈慑强吴。","诸葛不知命，肆逆乱天常。","拥徒十馀万，数来寇边疆。","我皇迈神武，秉钺镇雍凉。","亮乃畏天威，未战先仆僵。","盈虚自然运，时变固多艰。","东征陵海表，万里枭贼渊。","受遗齐七政，曹爽又滔天。","群凶受诛殛，百禄咸来臻。","黄华应福始，王凌为祸先。"]},{"t":"晋鼙舞歌五首 其三 景皇篇","f":"古风","c":["景皇帝。","聪明命世生。","盛德参天地。","帝王道大。","创基既已难。","继世亦未易。","外则夏侯玄。","内张则张与李。","三凶称逆。","乱帝纪。","顺天行诛。","穷其奸宄。","遏将御其渐。","潜谋不得起。","罪人咸伏辜。","威风振万里。","平衡综万机。","万机无不理。","召陵桓不君。","内外何纷纷。","众小便成群。","蒙昧恣心。","治乱不分。","睿圣独断。","济琥常以文。","顺天惟废立。","扫霓披浮云。","云霓既已辟。","清和未几间。","羽檄首尾至。","变起东南蕃。","俭钦为长蛇。","外则凭吴蛮。","万国纷骚扰。","戚戚天下惧不安。","神武御六军。","我皇秉钺征。","俭钦起寿春。","前锋据项城。","出其不意。","并纵奇兵。","奇兵诚难御。","庙胜实难支。","两军不期遇。","敌退计无施。","虎骑惟武进。","大战沙阳陂。","钦乃亡魂走。","奔虏若云披。","天恩赦有罪。","东土放鲸鲵。"]},{"t":"晋鼙舞歌五首 其四 大晋篇","f":"古风","c":["赫赫大晋。","于穆文皇。","荡荡巍巍。","道迈陶唐。","世称三皇五帝。","及今重其光。","九德克明。","文既显。","武又章。","恩弘六合。","兼济万方。","内举元凯。","朝政以纲。","外简虎臣。","时惟鹰扬。","靡顺不怀。","逆命斯亡。","仁配春日。","威逾秋霜。","济济多士。","同兹兰芳。","唐虞至治。","四了滔天。","致讨俭钦。","冈不肃虔。","化感海外。","海外来宾。","献其声乐。","并称妾臣。","西蜀猾夏。","僣号方域。","命将致讨。","委国稽服。","吴人放命。","凭海阻江。","飞书告谕。","响应来同。","先王建肆国。","九服为蕃卫。","亡秦坏诸侯。","享祚不二世。","历代不能复。","忽逾五百岁。","我皇迈圣德。","应期创典制。","分土五等。","蕃国正封界。","莘莘文武佐。","千秋遘嘉会。","洪业溢区内。","仁风翔海外。"]},{"t":"晋鼙舞歌五首 其五 明君篇","f":"五言古诗","c":["明君御四海，听鉴尽物情。","顾望有谴罚，竭忠身必荣。","兰茝出荒野，万里升紫庭。","茨草秽堂阶，扫截不得生。","能否莫相蒙，百官正其名。","恭己慎有为，有为无不成。","暗君不自信，群下执异端。","正直罹浸润，奸臣夺其权。","虽欲尽忠诚，结舌不敢言。","结舌亦何惮，尽忠为身患。","清流岂不洁，飞尘浊其源。","歧路令不迷，未远胜不还。","忠臣立君朝，正色不顾身。","邪正不并存，譬若胡与秦。","胡秦有合时，邪正各异津。","忠臣遇明君，乾乾惟日新。","群目统在纲，众星拱北辰。","设令遭暗主，斥退为凡民。","虽薄共时用，白茅犹可珍。","冰霜昼夜结，兰桂摧为薪。","邪臣多端变，用心何委曲。","便僻顺情指，动随君所欲。","偷安乐目前，不问清与浊。","积伪冈时主，养交以持禄。","言行恒相违，难餍其溪谷。","昧死射乾没，觉露则灭族。"]},{"t":"晋铎舞歌云门篇","f":"古风","c":["黄云门。","唐咸池。","虞韶舞。","夏夏殷沪。","列代有五。","振铎鸣金。","近大武。","清歌发唱。","形为主。","声和八音。","协律吕。","身不虚动。","手不徒举。","应节合度。","周其叙。","时奏宫角。","杂之以徵羽。","下餍众目。","上从钟鼓。","乐以移风。","与德礼要辅。","安有失其所。"]},{"t":"拂舞歌诗三首 其一 白鸠篇","f":"古风","c":["翩翩白鸠，载飞载鸣。","怀我君德，来集君庭。","白雀呈瑞，素羽明鲜。","翔庭舞异，以应仁乾。","交交鸣鸠，或丹或黄。","乐我君惠，振羽来翔。","东璧馀光，鱼在江湖。","惠而不费，敬我微躯。","策我良驷，习我驱驰。","与君周旋，乐道亡馀。","我心虚静，我志沾濡。","弹琴鼓瑟，聊以自娱。","凌云登台，浮游太清。","扳龙附凤，目望身轻。"]},{"t":"拂舞歌诗三首 其二 独漉篇","f":"古风","c":["独漉独漉，水深泥浊。","泥浊尚可，水深杀我。","雍雍双雁，游戏田畔。","我欲射雁，念子孤散。","翩翩浮萍，得风摇轻。","我心何合，与之同并。","空床低帷，谁知无人。","夜衣锦绣，谁别伪真。","刀鸣削中，倚床无施。","父冤不报，欲活何为。","猛虎斑斑，游戏山间。","虎欲齿人，不避豪贤。"]},{"t":"拂舞歌诗三首 其三 济济篇","f":"古风","c":["畅飞畅舞气流芳。","追念三五大绮黄。","去失有。","时可行。","去来同时此未央。","时冉冉。","近桑榆。","但当饮酒为欢娱。","衰老逝。","有何期。","多忧耿耿内怀思。","渊池广。","鱼独希。","愿得黄浦众所依。","恩感人。","世无比。","悲歌且舞无极已。"]},{"t":"白伫舞歌诗三首 其一","f":"七言古诗","c":["轻躯徐起何洋洋，高举两手白鹄翔。","宛若龙转乍低昂，凝停善睐容仪光。","如推若引留且行，随世而变诚无方。","舞以尽神安可忘，晋世方昌乐未央。","质如轻云色如银，爱之遗谁赠佳人。","制以为袍馀作巾，袍以光躯巾拂尘。","丽服在御会佳宾，醪醴盈樽美且淳。","清歌徐舞降只神，四座欢乐胡可陈。"]},{"t":"白伫舞歌诗三首 其二","f":"七言古诗","c":["双袂齐举鸾凤翔，罗裙飘遥昭仪光。","趋步生姿进流芳，鸣弦清歌及三阳。","人生世间如电过，乐时每少苦日多。","幸及良辰耀春华，齐倡献舞赵女歌。","羲和驰景逝不停，春露未晞严霜零。","百草凋索花落英，蟋蟀吟牖寒蝉鸣。","百年之命忽若倾，早知迅速秉烛行。","东造扶桑游紫庭，西至昆仑戏曾城。"]},{"t":"晋杯槃舞歌诗","f":"古风","c":["晋世宁。","四海平。","普天安东永大宁。","四海安。","天下欢。","乐治兴隆舞杯槃。","舞杯槃。","何翩翩。","举坐翻覆寿万年。","天与日。","终与一。","左回右转不相失。","筝笛悲。","酒舞疲。","心中慷慨呆健儿。","樽酒甘。","丝竹清。","愿令诸君醉复醒。","醉复醒。","时合同。","四座欢乐皆言工。","丝竹音。","可不听。","亦舞此槃左右轻。","自相当。","合坐欢乐人命长。","人命长。","当结友。","千秋万岁皆老寿。"]},{"t":"诗","f":"古风","c":["川崖惟平，其稼多黍。","旨酒嘉谷，可以养父。","野惟阜丘，彼稷多有。","嘉谷旨酒，可以养母。","惟月孟春，獭祭彼崖。","永言孝思，享祀孔嘉。","彼黍既洁，彼仪既泽。","蒸命良辰，祖考来格。","日月明明，亦惟其史。","谁能长生，不朽难获。","惟德实实，富贵何常。","我思古人，令问令望。"]},{"t":"云中诗","f":"古风","c":["相王沈醉，轻出教命。","捕贼千秋，干豫朝政。","王恺守常，国宝驰竞。","荆州大度，散诞难名。","盛德之流，法护王宁。","仲堪仙民，特有言咏。","东山安道，执操高抗。","何不徵之，以为朝匠。"]},{"t":"宣城民为陶汪歌","f":"七言古诗","c":["人当勤学得主簿。","谁使为之陶明府。"]},{"t":"石头民为庾亮歌二首 其一","f":"五言绝句","c":["庾公上武昌，翩翩如飞鸟。","庾公还扬州，白马牵旒旐。"]},{"t":"石头民为庾亮歌二首 其二","f":"五言绝句","c":["庾公初上时，翩翩如飞鸟。","庾公还扬州，白马牵流苏。"]},{"t":"升平中童歌","f":"五言古诗","c":["阿子汝闻不。"]},{"t":"升平末民歌","f":"古风","c":["白门廉。","宫庭廉。"]},{"t":"太和中百姓歌","f":"五言绝句","c":["青青御路杨，白马紫游鞭。","汝非皇太子，那得甘露浆。"]},{"t":"凤凰歌","f":"五言绝句","c":["凤凰生一雏，天下莫不喜。","本言是马驹，今定成龙子。"]},{"t":"荆州百姓歌","f":"古风","c":["黄昙英。","扬州大佛来上明。"]},{"t":"历阳百姓歌","f":"古风","c":["重罗黎。","重罗黎。","使君南上无还时。"]},{"t":"桓玄篡时小儿歌","f":"古风","c":["芒笼菌，绳缚腹。","车无轴，倚孤木。"]},{"t":"司马休之从者歌","f":"五言绝句","c":["可怜司马公，作性甚温良。","忆昔水边戏，使我不能忘。"]},{"t":"苻坚时关陇人歌","f":"古风","c":["长安大街，夹树杨槐。","下走朱轮，上有鸾栖。","英彦云集，诲我萌黎。"]},{"t":"苻坚时凤凰歌","f":"古风","c":["凤凰于飞。","其羽翼翼。","渊哉圣后。","龄万亿。"]},{"t":"苻坚时长安为慕容冲歌","f":"五言古诗","c":["一雌复一雄。","双飞入紫宫。"]},{"t":"平原为太守索棱歌","f":"古风","c":["懿矣明守，庶绩允厘。","剖符作宰，实获民思。"]},{"t":"越谣歌","f":"七言绝句","c":["卿虽乘车我戴笠，后日相逢下车揖。","我虽步行卿乘马，他日相逢卿当下。"]},{"t":"淫豫歌","f":"五言绝句","c":["滟预大如马，瞿塘不可下。","滟预大如牛，瞿塘不可流。"]},{"t":"淫豫歌","f":"五言绝句","c":["淫预大如马，瞿唐不可下。","淫预大如象，瞿唐不可上。"]},{"t":"巴东三峡歌二首 其一","f":"七言古诗","c":["巴东三峡巫峡长。","猿鸣三声泪沾裳。"]},{"t":"巴东三峡歌二首 其二","f":"七言古诗","c":["巴东三峡猿鸣悲。","猿鸣三声泪沾衣。"]},{"t":"巴东三峡歌","f":"七言古诗","c":["滩头白勃坚相持。","倏忽沦没别无期。"]},{"t":"武陵人歌","f":"楚辞体","c":["仰兹山兮迢迢。","层石构兮嵯峨。","朝日丽兮阳岩。","落景梁兮阴阿。","鄣壑兮生音。","吟籁兮相和。","敷芳兮绿林。","恬淡兮润波。","乐兹潭兮安流。","缓尔棹兮咏歌。"]},{"t":"闾里为消肠酒歌","f":"古风","c":["宁得醇酒消肠。","不与日月齐光。"]},{"t":"咸康二年童谣","f":"古风","c":["麦入土。","杀石虎。"]},{"t":"成帝末童谣","f":"五言古诗","c":["磕磕何隆隆。","驾车入梓宫。"]},{"t":"荆楚谣","f":"古风","c":["陶惟剑雄，像以神标。","云翔泥宿，邈何遥遥。","可以诚致，难以力招。"]},{"t":"吴中童谣","f":"古风","c":["宁食下湖荇。","不食湖上甘莼。","庾吴没命丧。","复杀王领军。"]},{"t":"哀帝隆和初童谣","f":"五言绝句","c":["升平不满斗，隆和那得久。","桓公入石头，陛下徒跣走。"]},{"t":"太和末童谣","f":"五言古诗","c":["犁牛耕御路，白门种小麦。"]},{"t":"京口民间谣二首 其一","f":"古风","c":["黄头小人欲作贼。","阿公在城下指缚得。"]},{"t":"京口民间谣二首 其二","f":"七言古诗","c":["黄头小人欲作乱。","赖得金刀作蕃捍。"]},{"t":"京口谣","f":"五言古诗","c":["昔年食白饭，今年食麦麸。","天公诛谪汝，教汝捻咙喉。","咙喉喝复喝，京口败复败。"]},{"t":"京口谣","f":"古风","c":["昔年食麦屑。","今年食豆。","豆不可食。","使我枯咙喉。"]},{"t":"孝武帝太元末京口谣","f":"古风","c":["黄雌鸡。","莫作雄父啼。","一旦去毛衣。","衣被拉飒栖。"]},{"t":"荆州童谣","f":"古风","c":["芒笼目，绳缚腹。","殷当败，桓当复。"]},{"t":"洪水谣","f":"古风","c":["雨若不止。","洪水必起。"]},{"t":"陇上童谣","f":"五言古诗","c":["十斗二升沙。","谁为王擢家。"]},{"t":"苻生时长安谣二首 其一","f":"七言古诗","c":["东海大鱼化为龙。","男便为王女为公。","问在何所洛门东。"]},{"t":"苻生时长安谣二首 其二","f":"五言绝句","c":["百里望空城，郁郁何青青。","瞎儿不知法，仰不见天星。"]},{"t":"苻坚时长安谣","f":"七言古诗","c":["凤凰凤凰止阿房。"]},{"t":"苻坚初童谣","f":"古风","c":["阿坚连牵。","三十年。","后若欲败时。","当在江湖边。"]},{"t":"苻坚时童谣","f":"五言古诗","c":["河水清复清。","苻诏死新城。"]},{"t":"苻坚时童谣","f":"七言古诗","c":["鱼羊田斗当灭秦。"]},{"t":"苻坚时长安谣","f":"七言古诗","c":["长鞘马鞭击左股。","太岁南行当复虏。"]},{"t":"凉州为张氏谣","f":"古风","c":["刘新妇簸米。","石新妇吹羖羝。","荡涤簸张儿。","张儿食之口正披。"]},{"t":"长安民谣","f":"七言古诗","c":["坚入五将山长得。"]},{"t":"苻坚国中谣","f":"古风","c":["谁谓尔坚。","石打碎。"]},{"t":"朔马谣","f":"五言绝句","c":["朔马心何悲，念旧中心劳。","燕雀何徘徊，意欲还故巢。"]},{"t":"燕童谣","f":"古风","c":["一束藁。","两头然。","秃头小儿来灭燕。"]},{"t":"大风谣","f":"七言绝句","c":["大风蓬勃扬尘埃。","八井三刀卒起来。","四海鼎沸中山颓。","惟有德人据三台。"]},{"t":"安帝元兴初童谣","f":"五言古诗","c":["草生及马腹。","乌啄桓玄目。"]},{"t":"安帝元兴初童谣","f":"七言古诗","c":["征钟落地桓迸走。"]},{"t":"安帝元兴中童谣","f":"古风","c":["长干巷。","巷长干。","今年杀郎君。","明年斩诸桓。"]},{"t":"安帝义熙初童谣","f":"七言古诗","c":["官家养芦化成荻。","芦生不止自成积。"]},{"t":"安帝义熙初谣二首 其一","f":"七言古诗","c":["芦生漫漫竟天半。"]},{"t":"安帝义熙初谣二首 其二","f":"古风","c":["芦橙橙。","逐水流。","东风忽如起。","那得入石头。"]},{"t":"晋世京师谣","f":"古风","c":["十丈瓦屋八九间。","芦作柱。","薤作栏。"]},{"t":"义熙中童谣","f":"七言古诗","c":["长有扫帚枢作杷。","扫除洛中迎琅琊。"]},{"t":"时人为庞世谣","f":"古风","c":["庞家之巷。","车马辚辚。","泥丸之日无吊宾。","吊宾不来何所因。","由性苛克寡所亲。"]},{"t":"三峡谣","f":"古风","c":["朝发黄牛，暮宿黄牛。","三朝三暮，黄牛如故。"]},{"t":"葛洪引谚","f":"古风","c":["太华之下。","白骨狼藉。"]},{"t":"葛洪引谚","f":"古风","c":["书三写。","鱼成鲁帝成虎。"]},{"t":"干宝引语","f":"五言古诗","c":["宗定伯卖鬼，得钱千五百。"]},{"t":"时人为习主簿语","f":"七言古诗","c":["徒三十年看儒书，不如一诣习主簿。"]},{"t":"桓温府为郗超王珣语","f":"古风","c":["髯参军。","短主簿。","能令公喜。","能令公怒。"]},{"t":"时人为谢安郗超王坦之语","f":"古风","c":["大才槃槃。","谢安家。","江东独步。","王文度。","盛德日新。","郗嘉宾。"]},{"t":"时人为郗超王坦之语","f":"古风","c":["盛德绝伦。","郗嘉宾。","江东独步。","王文度。"]},{"t":"时人为郗超王坦之语","f":"古风","c":["扬州独步。","王文度。","后来出人。","郗嘉宾。"]},{"t":"时人为王廙语","f":"古风","c":["王廙飞白，右军之亚。"]},{"t":"时人为王珉王珣语","f":"五言古诗","c":["法护非不佳，僧弥难为兄。"]},{"t":"时人为李始语","f":"古风","c":["欲养老。","属太保。"]},{"t":"长安为苻坚语","f":"古风","c":["欲得必存。","当举烟。"]},{"t":"时人世间梁氏兄弟语","f":"古风","c":["关东堂堂。","二申两房。","未若二梁。","环文绮章。"]},{"t":"祈嘉夜闻人呼语","f":"古风","c":["祈孔宾。","祈孔宾。","隐去来。","隐去来。","修饰人间。","甚苦不可谐。","所得未毛铢。","所丧如山崖。"]},{"t":"南燕人为公孙氏语","f":"古风","c":["欲得侯。","事五楼。"]},{"t":"西州为鞠氏游氏语","f":"古风","c":["鞠与游。","牛羊不数头。","南开朱门。","北望青楼。"]},{"t":"西州谚","f":"五言古诗","c":["李尹主敦煌。"]},{"t":"释道安引谚","f":"古风","c":["紫实昧朱，狂斯滥哲。"]},{"t":"时人为释道安语","f":"古风","c":["漆道人。","惊四邻。"]},{"t":"东山谚","f":"古风","c":["深量深思。","林谈识记。"]},{"t":"时人为卑罗语","f":"古风","c":["卑罗鄙语，慧观才录。","都人缮写，纸贵如玉。"]},{"t":"王子年引世语","f":"古风","c":["青雊鸣。","时太平。"]},{"t":"子夜歌四十二首 其一","f":"五言绝句","c":["落日出前门，瞻瞩见子度。","冶容多姿鬓，芳香已盈路。"]},{"t":"子夜歌四十二首 其二","f":"五言绝句","c":["芳是香所为，冶容不敢当。","天不夺人愿，故使侬见郎。"]},{"t":"子夜歌四十二首 其三","f":"五言绝句","c":["宿昔不梳头，丝发被两肩。","婉伸郎膝下，何处不可怜。"]},{"t":"子夜歌四十二首 其四","f":"五言绝句","c":["自从别欢来，奁器了不开。","头乱不敢理，粉拂生黄衣。"]},{"t":"子夜歌四十二首 其五","f":"五言绝句","c":["崎岖相怨慕，始获风云通。","玉林语石阙，悲思两心同。"]},{"t":"子夜歌四十二首 其六","f":"五言绝句","c":["见娘善容媚，愿得结金兰。","空织无经纬，求区理自难。"]},{"t":"子夜歌四十二首 其八","f":"五言绝句","c":["前丝断缠绵，意欲结交情。","春蚕易感化，丝子已复生。"]},{"t":"子夜歌四十二首 其九","f":"五言绝句","c":["今日已欢别，合会在何时。","明灯照空局，悠然未有期。"]},{"t":"子夜歌四十二首 其十","f":"五言绝句","c":["自从别郎来，何日不咨嗟。","黄檗郁成林，当奈苦心多。"]},{"t":"子夜歌四十二首 其十二","f":"五言绝句","c":["朝思出前门，暮思还后渚。","语笑向谁道，腹中阴忆汝。"]},{"t":"子夜歌四十二首 其十三","f":"五言绝句","c":["揽枕北窗卧，郎来就侬嬉。","小喜多唐突，相怜能几时。"]},{"t":"子夜歌四十二首 其十四","f":"五言绝句","c":["驻箸不能食，蹇蹇步闱里。","投琼著局上，终日走博子。"]},{"t":"子夜歌四十二首 其十五","f":"五言绝句","c":["郎为傍人取，负侬非一事。","摛门不安横，无复相关意。"]},{"t":"子夜歌四十二首 其十六","f":"五言绝句","c":["年少当及时，蹉跎日就老。","若不信侬语，但看霜下草。"]},{"t":"子夜歌四十二首 其十七","f":"五言绝句","c":["绿揽迮题锦，双裙今复开。","已许腰中带，谁共解罗衣。"]},{"t":"子夜歌四十二首 其十八","f":"五言绝句","c":["常虑有贰意，欢今果不齐。","枯鱼就浊水，长与清流乖。"]},{"t":"子夜歌四十二首 其十九","f":"五言绝句","c":["欢愁侬亦惨，郎笑我便喜。","不见连理树，异根同条起。"]},{"t":"子夜歌四十二首 其二十","f":"五言绝句","c":["感欢初殷勤，叹子后辽落。","打金侧玳瑁，外艳里怀薄。"]},{"t":"子夜歌四十二首 其二十一","f":"五言绝句","c":["别后涕流连，相思情悲满。","忆子腹糜烂，肝肠尺寸断。"]},{"t":"子夜歌四十二首 其二十二","f":"五言绝句","c":["道近不得数，遂致盛寒违。","不见东流水，何时复西归。"]},{"t":"子夜歌四十二首 其二十三","f":"五言绝句","c":["谁能思不歌，谁能饥不食。","日冥当户倚，惆怅底不忆。"]},{"t":"子夜歌四十二首 其二十四","f":"五言绝句","c":["揽裙未结带，约眉出前窗。","罗裳易飘飏，小开骂春风。"]},{"t":"子夜歌四十二首 其二十五","f":"五言绝句","c":["举酒待相劝，酒还杯亦空。","愿因微觞会，心感色亦同。"]},{"t":"子夜歌四十二首 其二十六","f":"五言绝句","c":["夜觉百思缠，忧叹涕流襟。","徒怀倾筐情，郎谁明侬心。"]},{"t":"子夜歌四十二首 其二十七","f":"五言绝句","c":["侬年不及时，其于作乖离。","素不知浮萍，转动春风移。"]},{"t":"子夜歌四十二首 其二十八","f":"五言绝句","c":["夜长不得眠，转侧听更鼓。","无故欢相逢，使侬肝肠苦。"]},{"t":"子夜歌四十二首 其二十九","f":"五言绝句","c":["欢从何处来，端然有忧色。","三唤不一应，有何比松柏。"]},{"t":"子夜歌四十二首 其三十","f":"五言绝句","c":["念爱情慊慊，倾倒无所惜。","重帘持自鄣，谁知许厚薄。"]},{"t":"子夜歌四十二首 其三十一","f":"五言绝句","c":["气清明月朗，夜与君共嬉。","郎歌妙意曲，侬亦吐芳词。"]},{"t":"子夜歌四十二首 其三十二","f":"五言绝句","c":["惊风急素柯，白日渐微濛。","郎怀幽闺性，侬亦恃春容。"]},{"t":"子夜歌四十二首 其三十四","f":"五言绝句","c":["人各既畴匹，我志独乖违。","风吹冬帘起，许时寒薄飞。"]},{"t":"子夜歌四十二首 其三十五","f":"五言绝句","c":["我念欢的的，子行由豫情。","雾露隐芙蓉，见莲不分明。"]},{"t":"子夜歌四十二首 其三十七","f":"五言绝句","c":["怜欢好情怀，移居作乡里。","桐树生门前，出入见梧子。"]},{"t":"子夜歌四十二首 其三十八","f":"五言绝句","c":["遣信欢不来，自往复不出。","金桐作芙蓉，莲子何能实。"]},{"t":"子夜歌四十二首 其三十九","f":"五言绝句","c":["初时非不密，其后日不如。","回头批栉脱，转觉薄志疏。"]},{"t":"子夜歌四十二首 其四十","f":"五言绝句","c":["寝食不相忘，同坐复俱起。","玉藕金芙蓉，无称我莲子。"]},{"t":"子夜歌四十二首 其四十二","f":"五言绝句","c":["朝日照绮钱，光风动纨素。","巧笑倩两犀，美目扬双蛾。"]},{"t":"子夜四时歌 春歌二十首 其二","f":"五言绝句","c":["绿荑带长路，丹椒重紫荆。","流吹出郊外，共欢弄春英。"]},{"t":"子夜四时歌 春歌二十首 其三","f":"五言绝句","c":["光风流月初，新林锦花舒。","情人戏春月，窈窕曳罗裾。"]},{"t":"子夜四时歌 春歌二十首 其四","f":"五言绝句","c":["妖冶颜荡骀，景色复多媚。","温风入南牖，织妇怀春意。"]},{"t":"子夜四时歌 春歌二十首 其五","f":"五言绝句","c":["碧楼冥初月，罗绮垂新风。","含春未及歌，桂酒发清容。"]},{"t":"子夜四时歌 春歌二十首 其六","f":"五言绝句","c":["杜鹃竹里鸣，梅花落满道。","燕女游春月，罗裳曳芳草。"]},{"t":"子夜四时歌 春歌二十首 其七","f":"五言绝句","c":["朱光照绿苑，丹华粲罗星。","那能闺中绣，独无怀春情。"]},{"t":"子夜四时歌 春歌二十首 其八","f":"五言绝句","c":["鲜云媚朱景，芳风散林花。","佳人步春苑，绣带飞纷葩。"]},{"t":"子夜四时歌 春歌二十首 其九","f":"五言绝句","c":["罗裳迮红袖，玉钗明月珰。","冶游步春露，艳觅同心郎。"]},{"t":"子夜四时歌 春歌二十首 其十一","f":"五言绝句","c":["新燕弄初调，杜鹃竞晨鸣。","画眉忘注口，游步散春情。"]},{"t":"子夜四时歌 春歌二十首 其十二","f":"五言绝句","c":["梅花落已尽，柳花随风散。","叹我当春年，无人相要唤。"]},{"t":"子夜四时歌 春歌二十首 其十三","f":"五言绝句","c":["昔别雁集渚，今还燕巢梁。","敢辞岁月久，但使逢春阳。"]},{"t":"子夜四时歌 春歌二十首 其十四","f":"五言绝句","c":["春园花就黄，阳池水方渌。","酌酒初满杯，调弦始成曲。"]},{"t":"子夜四时歌 春歌二十首 其十五","f":"五言绝句","c":["娉婷扬袖舞，阿那曲身轻。","照灼兰光在，容冶春风生。"]},{"t":"子夜四时歌 春歌二十首 其十六","f":"五言绝句","c":["阿那曜姿舞，逶迤唱新歌。","翠衣发华洛，回情一见过。"]},{"t":"子夜四时歌 春歌二十首 其十八","f":"五言绝句","c":["崎岖与时竞，不复自顾虑。","春风振荣林，常恐华落去。"]},{"t":"子夜四时歌 春歌二十首 其十九","f":"五言绝句","c":["思见春花月，含笑当道路。","逢侬多欲擿，可怜持自娱。"]},{"t":"子夜四时歌 夏歌二十首 其一","f":"五言绝句","c":["高堂不作壁，招取四面风。","吹欢罗裳开，动侬含笑容。"]},{"t":"子夜四时歌 夏歌二十首 其二","f":"五言绝句","c":["反覆华簟上，屏帐了不施。","郎君未可前，待我整容仪。"]},{"t":"子夜四时歌 夏歌二十首 其三","f":"五言绝句","c":["开春初无欢，秋冬更增凄。","共戏炎暑月，还觉两情谐。"]},{"t":"子夜四时歌 夏歌二十首 其四","f":"五言绝句","c":["春别犹春恋，夏还情更久。","罗帐为谁褰，双枕何时有。"]},{"t":"子夜四时歌 夏歌二十首 其五","f":"五言绝句","c":["叠扇放床上，企想远风来。","轻袖拂华妆，窈窕登高台。"]},{"t":"子夜四时歌 夏歌二十首 其六","f":"五言绝句","c":["含桃已中食，郎赠合欢扇。","深感同心意，兰室期相见。"]},{"t":"子夜四时歌 夏歌二十首 其七","f":"五言绝句","c":["田蚕事已毕，思妇犹苦身。","当暑理絺服，持寄与行人。"]},{"t":"子夜四时歌 夏歌二十首 其八","f":"五言绝句","c":["朝登凉台上，夕宿兰池里。","乘风采芙蓉，夜夜得莲子。"]},{"t":"子夜四时歌 夏歌二十首 其九","f":"五言绝句","c":["暑盛静无风，夏云薄暮起。","携手密叶下，浮瓜沈朱李。"]},{"t":"子夜四时歌 夏歌二十首 其十一","f":"五言绝句","c":["适见载青幡，三春已复倾。","林鹊改初调，林中夏蝉鸣。"]},{"t":"子夜四时歌 夏歌二十首 其十二","f":"五言绝句","c":["春桃初发红，惜色恐侬擿。","朱夏花落去，谁复相寻觅。"]},{"t":"子夜四时歌 夏歌二十首 其十三","f":"五言绝句","c":["昔别春风起，今还夏云浮。","路遥日月促，非是我淹留。"]},{"t":"子夜四时歌 夏歌二十首 其十四","f":"五言绝句","c":["青荷盖渌水，芙蓉葩红鲜。","郎见欲采我，我心欲怀莲。"]},{"t":"子夜四时歌 夏歌二十首 其十五","f":"五言绝句","c":["四周芙蓉池，朱堂敞无壁。","珍簟镂玉床，缱绻任怀适。"]},{"t":"子夜四时歌 夏歌二十首 其十六","f":"五言绝句","c":["赫赫盛阳月，无侬不握扇。","窈窕瑶台女，冶游戏凉殿。"]},{"t":"子夜四时歌 夏歌二十首 其十七","f":"五言绝句","c":["春倾桑叶尽，夏开蚕务毕。","昼夜理机丝，知欲早成匹。"]},{"t":"子夜四时歌 夏歌二十首 其十八","f":"五言绝句","c":["情知三夏热，今日偏独甚。","香巾拂玉席，共郎登楼寝。"]},{"t":"子夜四时歌 夏歌二十首 其十九","f":"五言绝句","c":["轻衣不重彩，飙风故不凉。","三伏何时过，许侬红粉妆。"]},{"t":"子夜四时歌 夏歌二十首 其二十","f":"五言绝句","c":["盛暑非游节，百虑相缠绵。","泛舟芙蓉湖，散思莲子间。"]},{"t":"子夜四时歌 秋歌十八首 其一","f":"五言绝句","c":["风清觉时凉，明月天色高。","佳人理寒服，万结砧杵劳。"]},{"t":"子夜四时歌 秋歌十八首 其二","f":"五言绝句","c":["清露凝如玉，凉风中夜发。","情人不还卧，冶游步明月。"]},{"t":"子夜四时歌 秋歌十八首 其三","f":"五言绝句","c":["鸿雁搴南去，乳燕指北飞。","征人难为思，愿逐秋风归。"]},{"t":"子夜四时歌 秋歌十八首 其四","f":"五言绝句","c":["开窗秋月光，灭烛解罗裳。","含笑帷幌里，举体兰蕙香。"]},{"t":"子夜四时歌 秋歌十八首 其五","f":"五言绝句","c":["适忆三阳初，今已九秋暮。","追逐泰始乐，不觉华年度。"]},{"t":"子夜四时歌 秋歌十八首 其六","f":"五言绝句","c":["飘飘初秋夕，明月耀秋辉。","握腕同游戏，庭含媚素归。"]},{"t":"子夜四时歌 秋歌十八首 其七","f":"五言绝句","c":["秋夜凉风起，天高星月明。","兰房竞妆饰，绮帐待双情。"]},{"t":"子夜四时歌 秋歌十八首 其八","f":"五言绝句","c":["凉风开窗寝，斜月垂光照。","中宵无人语，罗幌有双笑。"]},{"t":"子夜四时歌 秋歌十八首 其九","f":"五言绝句","c":["金风扇素节，玉露凝成霜。","登高去来雁，惆怅客心伤。"]},{"t":"子夜四时歌 秋歌十八首 其十","f":"五言绝句","c":["草木不常荣，憔悴为秋霜。","今遇泰始世，年逢九春阳。"]},{"t":"子夜四时歌 秋歌十八首 其十一","f":"五言绝句","c":["自从别欢来，何日不相思。","常恐秋叶零，无复莲条时。"]},{"t":"子夜四时歌 秋歌十八首 其十二","f":"五言绝句","c":["掘作九州池，尽是大宅里。","处处种芙蓉，婉转得莲子。"]},{"t":"子夜四时歌 秋歌十八首 其十三","f":"五言绝句","c":["初寒八九月，独缠自络丝。","寒衣尚未了，郎唤侬底为。"]},{"t":"子夜四时歌 秋歌十八首 其十四","f":"五言绝句","c":["秋爱两两雁，春感双双燕。","兰鹰接野鸡，雉落谁当见。"]},{"t":"子夜四时歌 秋歌十八首 其十五","f":"五言绝句","c":["仰头看桐树，桐花特可怜。","愿天无霜雪，梧子解千年。"]},{"t":"子夜四时歌 秋歌十八首 其十六","f":"五言绝句","c":["白露朝夕生，秋风凄长夜。","忆郎须寒服，乘月捣白素。"]},{"t":"子夜四时歌 秋歌十八首 其十八","f":"五言绝句","c":["别在三阳初，望远九秋暮。","恶见东流水，终年不西顾。"]},{"t":"子夜四时歌 冬歌十七首 其二","f":"五言绝句","c":["途涩无人行，冒寒往相觅。","若不信侬时，但看雪上迹。"]},{"t":"子夜四时歌 冬歌十七首 其三","f":"五言绝句","c":["寒鸟依高树，枯林鸣悲风。","为欢憔悴尽，那得好颜容。"]},{"t":"子夜四时歌 冬歌十七首 其四","f":"五言绝句","c":["夜半冒霜来，见我辄怨唱。","怀冰暗中倚，已寒不蒙亮。"]},{"t":"子夜四时歌 冬歌十七首 其五","f":"五言绝句","c":["蹑履步荒林，萧索悲人情。","一唱泰始乐，枯草衔花生。"]},{"t":"子夜四时歌 冬歌十七首 其六","f":"五言绝句","c":["昔别春草绿，今还墀雪盈。","谁知相思老，玄鬓白发生。"]},{"t":"子夜四时歌 冬歌十七首 其七","f":"五言绝句","c":["寒云浮天凝，积雪冰川波。","连山结玉岩，修庭振琼柯。"]},{"t":"子夜四时歌 冬歌十七首 其八","f":"五言绝句","c":["炭垆却夜寒，重袍坐叠褥。","与郎对华榻，弦歌秉兰烛。"]},{"t":"子夜四时歌 冬歌十七首 其九","f":"五言绝句","c":["天寒岁欲暮，朔风舞飞雪。","怀人重衾寝，故有三夏热。"]},{"t":"子夜四时歌 冬歌十七首 其十","f":"五言绝句","c":["冬林叶落尽，逢春已复曜。","葵藿生谷底，倾心不蒙照。"]},{"t":"子夜四时歌 冬歌十七首 其十一","f":"五言绝句","c":["朔风洒霰雨，绿池莲水结。","愿欢攘皓腕，共弄初落雪。"]},{"t":"子夜四时歌 冬歌十七首 其十二","f":"五言绝句","c":["严霜白草木，寒风昼夜起。","感时为欢叹，霜鬓不可视。"]},{"t":"子夜四时歌 冬歌十七首 其十三","f":"五言绝句","c":["何处结同心，西陵柏树下。","晃荡无四壁，严霜冻杀我。"]},{"t":"子夜四时歌 冬歌十七首 其十四","f":"五言绝句","c":["白雪停阴冈，丹华耀阳林。","何必丝与竹，山水有清音。"]},{"t":"子夜四时歌 冬歌十七首 其十五","f":"五言绝句","c":["未尝经辛苦，无故强相矜。","欲知千里寒，但看井水冰。"]},{"t":"子夜四时歌 冬歌十七首 其十七","f":"五言绝句","c":["适见三阳日，寒蝉已复鸣。","感时为欢叹，白发绿鬓生。"]},{"t":"子夜变歌三首 其一","f":"五言绝句","c":["人传欢负情，我自未尝见。","三更开门去，始知子夜变。"]},{"t":"子夜变歌三首 其二","f":"五言绝句","c":["岁月如流迈，春尽秋已至。","荧荧条上花，零落何乃驶。"]},{"t":"子夜变歌三首 其三","f":"五言绝句","c":["岁月如流迈，行已及素秋。","蟋蟀吟堂前，惆怅使侬愁。"]},{"t":"上声歌八首 其一","f":"五言绝句","c":["侬本是萧草，持作兰桂名。","芬芳顿交盛，感郎为上声。"]},{"t":"上声歌八首 其二","f":"五言绝句","c":["郎作上声曲，柱促使弦哀。","譬如秋风急，触遇伤侬怀。"]},{"t":"上声歌八首 其三","f":"五言绝句","c":["初歌子夜曲，改调促鸣筝。","四座暂寂静，听我歌上声。"]},{"t":"上声歌八首 其四","f":"五言绝句","c":["三鼓染乌头，闻鼓白门里。","揽裳抱履走，保冥不轻纪。"]},{"t":"上声歌八首 其五","f":"五言绝句","c":["三月寒暖适，杨柳可藏雀。","未言涕交零，如何见君隔。"]},{"t":"上声歌八首 其六","f":"五言绝句","c":["新衫绣两裆，迮著罗裙里。","行步动微尘，罗裙随风起。"]},{"t":"上声歌八首 其七","f":"五言绝句","c":["裲裆与郎著，反绣持贮里。","汗汗莫溅浣，持许相存在。"]},{"t":"上声歌八首 其八","f":"五言绝句","c":["春月暖何太，生裙迮罗袜。","暧暧日欲冥，从侬门前过。"]},{"t":"欢闻变歌六首 其一","f":"五言绝句","c":["金瓦九重墙，玉壁珊瑚柱。","中夜来相寻，唤欢闻不顾。"]},{"t":"欢闻变歌六首 其二","f":"五言绝句","c":["欢来不徐徐，阳窗都锐户。","耶㜑尚未眠，肝心如椎橹。"]},{"t":"欢闻变歌六首 其三","f":"五言绝句","c":["张罾不得鱼，不橹罾空归。","君非鸬鹚鸟，底为守空池。"]},{"t":"欢闻变歌六首 其四","f":"五言绝句","c":["刻木作班鹪，有翅不能飞。","摇著帆樯上，望见千里矶。"]},{"t":"欢闻变歌六首 其六","f":"五言绝句","c":["驶风何曜曜，帆上牛渚矶。","帆作伞子张，船如侣马驰。"]},{"t":"前溪歌七首 其一","f":"五言绝句","c":["忧思出门倚，逢郎前溪度。","莫作流水心，引新都舍故。"]},{"t":"前溪歌七首 其二","f":"五言绝句","c":["为家不凿井，担瓶下前溪。","开穿乱漫下，但闻林鸟啼。"]},{"t":"前溪歌七首 其三","f":"五言绝句","c":["逍遥独桑头，北望东武亭。","黄瓜被山侧，春风感郎情。"]},{"t":"前溪歌七首 其四","f":"五言绝句","c":["黄葛生烂熳，谁能断葛根。","宁断娇儿乳，不断郎殷勤。"]},{"t":"前溪歌七首 其六","f":"五言古诗","c":["逍遥独桑头。","东北广无亲。","黄瓜是小草。","春风何足叹。","忆汝涕交零。"]},{"t":"前溪歌七首 其七","f":"五言古诗","c":["前溪沧浪映。","通波澄渌清。","声弦传不绝。","千载寄汝名。","永兴天地并。"]},{"t":"阿子歌三首 其一","f":"五言绝句","c":["阿子复阿子，念汝好颜容。","风流世希有，窈窕无人双。"]},{"t":"阿子歌三首 其二","f":"五言绝句","c":["春月故鸭啼，独雄颠倒落。","工知悦弦死，故来相寻博。"]},{"t":"阿子歌三首 其三","f":"五言绝句","c":["野田草欲尽，东流水又暴。","念我双飞凫，饥渴常不饱。"]},{"t":"团扇郎六首 其一","f":"五言绝句","c":["七宝画团扇，灿烂明月光。","饷郎却暄暑，相忆莫相忘。"]},{"t":"团扇郎六首 其三","f":"五言绝句","c":["犊车薄不乘，步行耀玉颜。","逢侬都共语，起欲著夜半。"]},{"t":"团扇郎六首 其四","f":"五言绝句","c":["团扇薄不摇，窈窕摇蒲葵。","相怜中道罢，定是阿谁非。"]},{"t":"团扇郎六首 其五","f":"五言绝句","c":["御路薄不行，窈窕决横塘。","团扇鄣白日，面作芙蓉光。"]},{"t":"团扇郎六首 其六","f":"五言绝句","c":["白练薄不著，趣欲著锦衣。","异色都言好，清白为谁施。"]},{"t":"七日夜女郎歌九首 其一","f":"五言绝句","c":["三春怨离泣，九秋欣期歌。","驾鸾行日时，月明济长河。"]},{"t":"七日夜女郎歌九首 其二","f":"五言绝句","c":["长河起秋云，汉渚风凉发。","含欣出霄路，可笑向明月。"]},{"t":"七日夜女郎歌九首 其三","f":"五言绝句","c":["金风起汉曲，素月明河边。","七章未成匹，飞燕起长川。"]},{"t":"七日夜女郎歌九首 其四","f":"五言绝句","c":["春离隔寒暑，明秋暂一会。","两叹别日长，双情苦饥渴。"]},{"t":"七日夜女郎歌九首 其五","f":"五言绝句","c":["婉娈不终夕，一别周年期。","桑蚕不作茧，昼夜长悬丝。"]},{"t":"七日夜女郎歌九首 其六","f":"五言绝句","c":["灵匹怨离处，索居隔长河。","玄云不应雷，是侬啼叹歌。"]},{"t":"七日夜女郎歌九首 其七","f":"五言绝句","c":["振玉下金阶，拭眼瞩星兰。","惆怅登云轺，悲恨两情殚。"]},{"t":"七日夜女郎歌九首 其八","f":"五言绝句","c":["风骖不驾缨，翼人立中庭。","箫管且停吹，展我叙离情。"]},{"t":"七日夜女郎歌九首 其九","f":"五言绝句","c":["紫霞烟翠盖，斜月照绮窗。","衔悲握离袂，易尔还年容。"]},{"t":"长史变歌三首 其一","f":"五言绝句","c":["出侬吴昌门，清水绿碧色。","徘徊戎马间，求罢不能得。"]},{"t":"长史变歌三首 其二","f":"五言绝句","c":["日和狂风扇，心故清白节。","朱门前世荣，千载表忠烈。"]},{"t":"长史变歌三首 其三","f":"五言绝句","c":["朱桂结贞根，芬芳溢帝庭。","陵霜不改色，枝叶永流荣。"]},{"t":"黄生曲三首 其一","f":"五言绝句","c":["黄生无诚信，冥强将侬期。","通夕出门望，至晚竟不来。"]},{"t":"黄生曲三首 其二","f":"五言绝句","c":["崔子信桑条，馁去多馁还。","为欢复摧折，命生丝发间。"]},{"t":"黄生曲三首 其三","f":"五言绝句","c":["松柏叶青倩，石榴花葳蕤。","迮置前后事，欢今定怜谁。"]},{"t":"黄鹄曲四首 其一","f":"五言绝句","c":["黄鹄参天飞，半道郁徘徊。","腹中车轮转，君知思忆谁。"]},{"t":"黄鹄曲四首 其二","f":"五言绝句","c":["黄鹄参天飞，半道还哀鸣。","三年失群侣，生离伤人情。"]},{"t":"黄鹄曲四首 其三","f":"五言绝句","c":["黄鹄参天飞，凝翮争风回。","高翔入率阙，时复乘云颓。"]},{"t":"黄鹄曲四首 其四","f":"五言绝句","c":["黄鹄参天飞，半道还后渚。","欲飞复不飞，悲鸣觅群侣。"]},{"t":"桃叶歌三首 其一","f":"五言绝句","c":["桃叶映红枝，无风自婀娜。","春花映何限，感郎独采我。"]},{"t":"桃叶歌三首 其二","f":"五言绝句","c":["桃叶复桃叶，桃树连桃根。","相怜两乐事，独使我殷勤。"]},{"t":"桃叶歌三首 其三","f":"五言绝句","c":["桃叶复桃叶，渡江不用楫。","但渡无所苦，我自来迎接。"]},{"t":"桃叶歌","f":"五言绝句","c":["桃叶复桃叶，渡江不待橹。","风波了无常，没命江南渡。"]},{"t":"长乐佳七首 其一","f":"五言绝句","c":["小庭春映日，四角佩琳琅。","玉枕龙须席，郎瞑首何当。"]},{"t":"长乐佳七首 其二","f":"五言绝句","c":["雎鸠不集林，体洁好清流。","贞节曜奇世，长乐戏汀洲。"]},{"t":"长乐佳七首 其三","f":"五言绝句","c":["鸳鸯翻碧树，皆以戏兰渚。","寝食不相离，长莫过时许。"]},{"t":"长乐佳七首 其四","f":"古风","c":["比翼交颈游。","千载不相离。","偕情欣欢。","念长乐佳。"]},{"t":"长乐佳七首 其五","f":"五言古诗","c":["欲知长乐佳。","中陵罗淑女。","媚兰双情谐。"]},{"t":"长乐佳七首 其六","f":"五言古诗","c":["欲知长乐佳。","中陵罗雎鸠。","美死两心齐。"]},{"t":"长乐佳七首 其七","f":"五言古诗","c":["欲知长乐佳。","中陵罗背林。","前溪长相随。"]},{"t":"欢好曲三首 其一","f":"五言绝句","c":["淑女总角时，唤作小姑子。","容艳初春花，人见谁不爱。"]},{"t":"欢好曲三首 其二","f":"五言绝句","c":["窈窕上头欢，那得及破瓜。","但看脱叶莲，何如芙蓉花。"]},{"t":"欢好曲三首 其三","f":"五言绝句","c":["逶迤总角年，华艳星间月。","遥见情倾处，不觉喉中哕。"]},{"t":"懊侬歌十四首 其一","f":"五言绝句","c":["丝布涩难缝，令侬十指穿。","黄牛细犊车，游戏出孟津。"]},{"t":"懊侬歌十四首 其二","f":"五言绝句","c":["江中白布帆，乌布礼中帷。","潭如陌上鼓，许是侬欢归。"]},{"t":"懊侬歌十四首 其四","f":"五言绝句","c":["寡妇哭城颓，此情非虚假。","相乐不相得，抱恨黄泉下。"]},{"t":"懊侬歌十四首 其五","f":"五言绝句","c":["内心百际起，外形空殷勤。","既就颓城感，敢言浮花言。"]},{"t":"懊侬歌十四首 其六","f":"五言绝句","c":["我与欢相怜，约誓底言者。","常叹负情人，郎今果成诈。"]},{"t":"懊侬歌十四首 其七","f":"五言绝句","c":["我有一所欢，安在深阖里。","桐树不结花，何有得梧子。"]},{"t":"懊侬歌十四首 其九","f":"五言绝句","c":["暂薄牛渚矶，欢不下延板。","水深沾侬衣，白黑何在浣。"]},{"t":"懊侬歌十四首 其十","f":"五言绝句","c":["爱子好情怀，倾家料理乱。","揽裳未结带，落托行人断。"]},{"t":"懊侬歌十四首 其十一","f":"五言绝句","c":["月落天欲曙，能得几时眠。","凄凄下床去，侬病不能言。"]},{"t":"懊侬歌十四首 其十二","f":"五言绝句","c":["发乱谁料理，托侬言相思。","还君华艳去，催送实情来。"]},{"t":"懊侬歌十四首 其十三","f":"古风","c":["山头草。","欢少四面风。","趋使侬颠倒。"]},{"t":"懊侬歌十四首 其十四","f":"五言古诗","c":["懊恼奈何许。","夜闻家中论。","不得侬与汝。"]},{"t":"神弦歌十一首 其一 宿阿曲","f":"五言绝句","c":["苏林开天门，赵尊闭地户。","神灵亦道同，真官今来下。"]},{"t":"神弦歌十一首 其二 道君曲","f":"古风","c":["中庭有树自语，梧桐推枝布叶。"]},{"t":"神弦歌十一首 其三 圣郎曲","f":"五言古诗","c":["左亦不佯佯，右亦不翼翼。","仙人在郎傍，玉女在郎侧。","酒无沙糖味，为他通颜色。"]},{"t":"神弦歌十一首 其四 娇女诗","f":"五言古诗","c":["北游临河海，遥望中菰菱。","芙蓉发盛华，渌水清且澄。","弦歌奏声节，仿佛有馀音。","蹀躞越桥上，河水东西流。","上有神仙居，下有西流鱼。","行不独自去，三三两两俱。"]},{"t":"神弦歌十一首 其五 白石郎曲","f":"古风","c":["白石郎。","临江居。","前导江伯后从鱼。","积石如玉。","列松如翠。","郎艳得绝。","世无其二。"]},{"t":"神弦歌十一首 其六 青溪小姑曲","f":"古风","c":["开门白水，侧近桥梁。","小姑所居，独处无郎。"]},{"t":"神弦歌十一首 其七 湖就姑曲","f":"五言古诗","c":["赤山湖就头，孟阳二三月。","绿蔽贲荇薮，湖就赤山矶。","大姑大湖东，仲姑居湖西。"]},{"t":"神弦歌十一首 其八 姑恩曲","f":"古风","c":["明姑遵八风。","蕃谒云日中。","前导陆离兽后从。","朱鸟麟凤凰。","苕苕山头柏。","冬夏叶不衰。","独当被天恩。","枝叶华葳蕤。"]},{"t":"神弦歌十一首 其九 采莲童曲","f":"五言律诗","c":["泛舟采菱叶，过摘芙蓉花。","扣楫命童侣，齐声采莲歌。","东湖扶菰童，西湖采菱芰。","不持歌作乐，为持解愁思。"]},{"t":"神弦歌十一首 其十 明下童曲","f":"五言律诗","c":["走马上前阪，石子弹马蹄。","不惜弹马蹄，但惜马上儿。","陈孔骄赭白，陆郎乘班骓。","徘徊射堂头，望门不欲归。"]},{"t":"神弦歌十一首 其十一 同生曲","f":"五言律诗","c":["人生不满百，常抱千岁忧。","早知人命促，秉烛夜行游。","岁月如流迈，行已及素秋。","蟋蟀鸣空堂，感怅令人忧。"]},{"t":"三洲歌 其一","f":"五言绝句","c":["送欢板桥湾，相待三山头。","遥见千幅帆，知是逐风流。"]},{"t":"三洲歌 其二","f":"五言绝句","c":["风流不暂停，三山隐行舟。","愿作比目鱼，随欢千里游。"]},{"t":"三洲歌 其三","f":"五言绝句","c":["湘东醽醁酒，广州龙头铛。","玉樽金镂椀，与郎双杯行。"]},{"t":"采桑度 其二","f":"五言绝句","c":["冶游采桑女，尽有芳春色。","姿容应春媚，粉黛不加饰。"]},{"t":"采桑度 其四","f":"五言绝句","c":["语欢稍养蚕，一头养百塸。","奈当黑瘦尽，桑叶常不周。"]},{"t":"采桑度 其五","f":"五言绝句","c":["春月采桑时，林下与欢俱。","养蚕不满百，那得罗绣襦。"]},{"t":"采桑度 其七","f":"五言绝句","c":["伪蚕化作茧，烂熳不成丝。","徒劳无所获，养蚕持底为。"]},{"t":"江陵乐 其一","f":"五言绝句","c":["不复蹋踶人，踶地地欲穿。","盆隘欢绳断，蹋坏绛罗裙。"]},{"t":"江陵乐 其二","f":"五言绝句","c":["不复出场戏，踶场生青草。","试作两三回，踶场方就好。"]},{"t":"江陵乐 其三","f":"五言绝句","c":["阳春二三月，相将蹋百草。","逢人驻上看，扬声皆言好。"]},{"t":"江陵乐 其四","f":"五言绝句","c":["暂出后园看，见花多忆子。","乌鸟双双飞，侬欢今何在。"]},{"t":"青阳度 其一","f":"五言绝句","c":["隐机倚不织，寻得烂熳丝。","成匹郎莫断，忆侬经绞时。"]},{"t":"青骢白马","f":"七言古诗","c":["青骢白马紫丝缰，可怜石桥根柏梁。","汝忽千里去无常，愿得到头还故乡。","系马可怜著长松，游戏徘徊五湖中。","借问湖中采菱妇，莲子青荷可得否。","可怜白马高缠騣，著地踯躅多徘徊。","问君可怜六萌车，迎取窈窕西曲娘。","问君可怜下都去，何得见君复西归。","齐唱可怜使人惑，昼夜怀欢何时忘。"]},{"t":"安东平五曲 其一","f":"古风","c":["凄凄烈烈，北风为雪。","船道不通，步道断绝。"]},{"t":"安东平五曲 其二","f":"古风","c":["吴中细布，阔幅长度。","我有一端，与郎作裤。"]},{"t":"安东平五曲 其三","f":"古风","c":["微物虽轻，拙手所作。","馀有三丈，为郎别厝。"]},{"t":"安东平五曲 其四","f":"古风","c":["制为轻巾，以奉故人。","不持作好，与郎拭尘。"]},{"t":"安东平五曲 其五","f":"古风","c":["东平刘生，复感人情。","与郎相知，当解千龄。"]},{"t":"女儿子 其一","f":"七言古诗","c":["巴东三峡猿鸣悲。","夜鸣三声泪沾衣。"]},{"t":"女儿子 其二","f":"七言古诗","c":["我欲上蜀蜀水难。","蹋蹀珂头腰环环。"]},{"t":"来罗 其一","f":"五言绝句","c":["郁金黄花标，下有同心草。","草生日已长，人生日就老。"]},{"t":"来罗 其二","f":"五言绝句","c":["君子防示然，莫近嫌疑边。","瓜田不蹑履，李下不正冠。"]},{"t":"来罗 其三","f":"五言绝句","c":["故人何怨新，切少必求多。","此事何足道，听我歌来罗。"]},{"t":"来罗 其四","f":"五言绝句","c":["白头不忍死，心愁皆敖然。","游戏泰始世，一日当千年。"]},{"t":"那呵滩 其一","f":"五言绝句","c":["我去只如还。","终不在道边。","我若在道边。","良信寄书还。"]},{"t":"那呵滩 其二","f":"五言绝句","c":["沿江引百丈，一濡多一艇。","水上郎担篙，何时至江陵。"]},{"t":"那呵滩 其三","f":"五言绝句","c":["江陵三千三，何足特作远。","书疏数知闻，莫令信使断。"]},{"t":"那呵滩 其四","f":"五言绝句","c":["闻欢下扬州，相送江津湾。","愿得篙橹折，交郎到头还。"]},{"t":"那呵滩 其五","f":"五言绝句","c":["篙折当更觅，橹折当更安。","各自是官人，那得到头还。"]},{"t":"那呵滩 其六","f":"五言绝句","c":["百思缠中心，憔悴为所欢。","与子结终始，折约在金兰。"]},{"t":"孟珠 其一","f":"五言绝句","c":["人言孟珠富，信实金满堂。","龙头衔九花，玉钗明月珰。"]},{"t":"孟珠 其二","f":"五言绝句","c":["阳春二三月，草与水同色。","攀条摘香花，言是欢气息。"]},{"t":"孟珠 其一","f":"五言绝句","c":["人言春复著，我言未渠央。","暂出后湖看，蒲菰如许长。"]},{"t":"孟珠 其二","f":"五言绝句","c":["扬州石榴花，摘插双襟中。","葳蕤当忆我，莫持艳他侬。"]},{"t":"孟珠 其四","f":"五言绝句","c":["望欢四五年，实情将懊恼。","愿得无人处，回身与郎抱。"]},{"t":"孟珠 其五","f":"五言绝句","c":["阳春二三月，正是养蚕时。","那得不相怨，其再许侬来。"]},{"t":"孟珠 其六","f":"五言绝句","c":["将欢期三更，合冥欢如何。","走马放苍鹰，飞驰赴郎期。"]},{"t":"孟珠 其七","f":"五言绝句","c":["适闻梅作花，花落已成子。","杜鹃绕林啼，思从心下起。"]},{"t":"孟珠 其八","f":"五言绝句","c":["可怜景阳山，苕苕百尺楼。","上有明天子，麟凤戏中州。"]},{"t":"翳乐","f":"五言绝句","c":["人生欢爱时，少年新得意。","一旦不相见，辄作烦冤思。"]},{"t":"翳乐 其一","f":"五言绝句","c":["阳春二三月，相将舞翳乐。","曲曲随时变，持许艳郎目。"]},{"t":"翳乐 其二","f":"五言绝句","c":["人言扬州乐，扬州信自乐。","总角诸少年，歌舞自相逐。"]},{"t":"月节折杨柳歌十三首 其一 正月歌","f":"古风","c":["春风尚萧条。","去故来如新。","苦心非一朝。","折杨柳。","愁思满腹中。","历乱不可数。"]},{"t":"月节折杨柳歌十三首 其二 二月歌","f":"古风","c":["翩翩乌入乡。","道逢双燕飞。","劳君看三阳。","折杨柳。","寄言语侬欢。","寻还不复久。"]},{"t":"月节折杨柳歌十三首 其三 三月歌","f":"古风","c":["泛舟临曲池。","仰头看春花。","杜鹃纬林啼。","折杨柳。","双下俱徘徊。","我与欢共取。"]},{"t":"月节折杨柳歌十三首 其四 四月歌","f":"古风","c":["芙蓉始怀莲。","何处觅同心。","俱生世尊前。","折杨柳。","捻香散名花。","志得长相取。"]},{"t":"月节折杨柳歌十三首 其五 五月歌","f":"古风","c":["菰生四五尺。","素身为谁珍。","盛年将可惜。","折杨柳。","作得九子粽。","思想劳欢手。"]},{"t":"月节折杨柳歌十三首 其六 六月歌","f":"古风","c":["三伏热如火。","笼窗开北牖。","与郎对榻坐。","折杨柳。","同塸贮蜜浆。","不用水洗溴。"]},{"t":"月节折杨柳歌十三首 其七 七月歌","f":"古风","c":["织女游河边。","牵牛顾自叹。","一会复周年。","折杨柳。","揽结长命草。","同心不相负。"]},{"t":"月节折杨柳歌十三首 其八 八月歌","f":"古风","c":["迎欢裁衣裳。","日月如流水。","白露凝庭霜。","折杨柳。","夜闻捣衣声。","窈窕谁家妇。"]},{"t":"月节折杨柳歌十三首 其九 九月歌","f":"古风","c":["甘菊吐黄花。","非无杯觞用。","当奈许寒何。","折杨柳。","授欢罗衣裳。","含笑言不取。"]},{"t":"月节折杨柳歌十三首 其十 十月歌","f":"古风","c":["大树转萧索。","天阴不作雨。","严霜半夜落。","折杨柳。","林中与松柏。","岁寒不相负。"]},{"t":"月节折杨柳歌十三首 其十一 十一月歌","f":"古风","c":["素雪任风流。","树木转枯悴。","松柏无所忧。","折杨柳。","寒衣履薄冰。","欢讵知侬否。"]},{"t":"月节折杨柳歌十三首 其十二 十二月歌","f":"古风","c":["天寒岁欲暮。","春秋及冬夏。","苦心停欲度。","折杨柳。","沉乱枕席间。","缠绵不觉久。"]},{"t":"月节折杨柳歌十三首 其十三 闰月歌","f":"古风","c":["成闰暑与寒。","春秋补小月。","念子时无间。","折杨柳。","阴阳推我去。","那得有定主。"]},{"t":"长干曲","f":"五言绝句","c":["逆流故相邀，菱舟不怕摇。","妾家杨子住，便弄广陵潮。"]},{"t":"休洗红二首 其一","f":"古风","c":["休洗红。","洗多红色淡。","不惜故缝衣。","记得初按茜。","人寿百年能几何。","后来新妇今为婆。"]},{"t":"休洗红二首 其二","f":"古风","c":["休洗红。","洗我红在水。","新红裁作衣。","旧红番作里。","回黄转绿无定期。","世事返复君所知。"]},{"t":"吴趋行","f":"五言绝句","c":["茧满盖重帘，唯有远相思。","藕叶清朝钏，何见早归时。"]},{"t":"曲池歌","f":"五言古诗","c":["曲池何淡澹，芙蓉蔽清源。","荣华盛壮时，见者谁不欢。","一朝光采落，见者不回颜。"]},{"t":"梦蓬莱四真人作诗四首 其一 石庆安作","f":"五言古诗","c":["灵山造太霞，竖岩绝霄峰。","紫烟散神州，乘飙驾白龙。","相携四宾人，东朝桑林公。","广休年虽前，壮气何蒙蒙。","实未下路让，惟年以相崇。"]},{"t":"梦蓬莱四真人作诗四首 其二 张诱世作","f":"五言古诗","c":["北游太漠外，来登蓬莱阙。","紫云构灵宫，香烟何郁郁。","美哉洛广休，久在论道位。","罗并真人坐，齐观白龙迈。","离世四人用，何时共解带。","有怀披襟友，欣欣高晨会。"]},{"t":"梦蓬莱四真人作诗四首 其三 许玉斧作","f":"五言古诗","c":["游观奇山峙，漱濯沧流清。","遥观蓬莱间，屹屹冲霄冥。","五芝被绛岩，四阶植琳琼。","纷纷灵华散，晃晃焕神庭。","从容七觉外，任我摄天生。","自足方寸里，何用白龙荣。"]},{"t":"梦蓬莱四真人作诗四首 其四 丁玮宁作","f":"五言古诗","c":["玄山构沧浪，金房映灵轩。","洛公挺奇尚，从容有无间。","形沉北寒宇，三神栖九天。","同寮相率往，推我高胜年。","弱冠石庆安，未肯崇尊贤。","嘲笑蓬莱公，呼此广休前。","明公将何以，却此少年翰。"]},{"t":"十月十五日右英夫人说诗令疏四首 其一 青童大君常吟咏","f":"五言绝句","c":["欲植灭度根，当拔生死栽。","沉吟堕九泉，但坐惜形骸。"]},{"t":"十月十五日右英夫人说诗令疏四首 其二 太虚真人常吟咏","f":"五言律诗","c":["观神载形时，亦如车从马。","车败马奔亡，牵连一时假。","哀世莫识此，但是惜风火。","种罪天网上，受毒地狱下。"]},{"t":"十月十五日右英夫人说诗令疏四首 其三 西域真人王君常吟咏","f":"五言古诗","c":["形为渡神舟，薄岸当别去。","形非神常宅，神非形常载。","徘徊生死轮，但苦心犹豫。"]},{"t":"十月十五日右英夫人说诗令疏四首 其四 小有真人王君常吟咏","f":"五言律诗","c":["失道从死津，三魂迷生道。","生生日已远，死死日已早。","悲哉苦痛客，根华已颠倒。","起就零落生，焉知反枯老。"]},{"t":"方诸宫东华上房灵妃歌曲","f":"五言古诗","c":["紫桂植瑶园，朱华声凄凄。","月宫生蕊渊，日中有琼池。","左拔员灵曜，右制丹霞晖。","流金焕绛庭，八景绝烟回。","绿盖浮明朗，控节命太微。","凤精童华颜，琳腴充长饥。","控晨揖太素，乘飙翔玉墀。","吐纳六虚气，玉嫔把巾随。","弹璈南云扇，香风鼓锦披。","叩商百兽舞，六天摄神威。","倏欻亿万春，龄纪郁巍巍。","小鲜未烹鼎，言我岩下悲。"]},{"t":"太微玄清左夫人北渟宫中歌曲 其一","f":"五言古诗","c":["郁蔼非真墟，太无为我馆。","玄公岂有怀，萦蒙孤所难。","落凤控紫霞，矫辔登晨岸。","寂寂无濠涯，晖晖空中观。","隐芝秀凤丘，逡巡瑶林畔。","龙胎婴尔形，八琼回素旦。","琅华繁玉宫，结葩凌岩粲。","鹏扇绝亿岭，抚翮凌霄翰。","西庭命长歌，云璈乘虚弹。","八风缠绿宇，丛烟豁然散。","灵童掷流金，太微启璧案。","三光折腰舞，紫皇挥袂赞。"]},{"t":"太微玄清左夫人北渟宫中歌曲 其二","f":"五言古诗","c":["朗朗扇景曜，晔晔长庚焕。","超軿竦明刃，下眄使我惋。","愿哀地仙辈，何为栖林涧。"]},{"t":"魏夫人与众真吟诗二首 其一 兴宁四年丙寅四月二十七日夜降杨羲家作","f":"五言古诗","c":["玄感妙象外，和声自相招。","灵云郁紫晨，兰风扇绿轺。","上真宴琼台，邈为地仙标。","所期贵远迈，故能秀颖翘。","玩彼八素翰，道成初不辽。","人事胡可豫，使尔形气销。"]},{"t":"魏夫人与众真吟诗二首 其二 十二月一日夜南岳夫人作与许长史","f":"五言古诗","c":["灵谷秀兰荣，藏身栖岩京。","被褐均衮龙，带索齐玉鸣。","表盘幽辽里，掷神太霞庭。","霄上有陛贤，空中有真声。","抑我曲晨飞，案此绿轩軿。","下观八度内，俯叹风尘萦。","解脱遗波浪，登此眇眇清。","扰竞三津渴，奔驰割尔龄。"]},{"t":"南极王夫人诗","f":"五言古诗","c":["林振须类感，云蔚待龙吟。","玄数自相求，触节皆有音。","飞軿出西华，总辔忽来寻。","八遐非无娱，同咏理自钦。","悼此四维内，百忧常在心。","俱游北寒台，神风开尔襟。"]},{"t":"辛玄子赠诗三首 其一","f":"五言古诗","c":["畴昔入冥乡，顺驾应灵招。","神随空无散，气与庆云消。","形非明玉质，玄匠安能雕。","蹀足吟幽唱，仰手玩鸣条。","林室有逸欢，绝此轩外交。","遗景附圆曜，嘉音何寥寥。"]},{"t":"辛玄子赠诗三首 其二","f":"五言古诗","c":["寂通寄兴感，玄气摄动音。","高轮虽参差，万仞故来寻。","萧萧研道子，合神契灵衿。","委顺浪世化，心标窈窕林。","同期理外游，相与静东岑。"]},{"t":"辛玄子赠诗三首 其三","f":"五言律诗","c":["命驾广酆阿，逸迹幽冥乡。","空中自有物，有中亦无常。","悟言有无际，相与会濠梁。","目击玄解了，鬼神理自忘。"]},{"t":"紫微夫人授乞食公歌","f":"五言古诗","c":["天庭发双华，山源彰阴邪。","清晨按天马，来诣太真家。","真人无那隐，又以灭百魔。"]},{"t":"南岳夫人授太上宫中歌","f":"五言古诗","c":["手把八云气，英明守二重。","太真握明镜，鉴合日月锋。","云仪拂高阙，开括泥丸宫。","万响入百关，骄女坐玄房。","愈行愈鲜盛，英灵自尔通。"]},{"t":"大洞真经诗","f":"五言律诗","c":["扶晨始晖生，紫云映玄阿。","焕洞圆光蔚，晃朗濯曜罗。","眇眇灵景元，森洒空清华。","九天馆玉宾，金房烟霄歌。"]},{"t":"八月十六日夕请灵真人授诗","f":"五言律诗","c":["拟驾东岑人，停景招隐静。","仁德乘波来，俱会三秀岭。","灵芝信可食，使尔无终永。","吸真献金浆，不待百丈井。"]},{"t":"谚谣","f":"古风","c":["杨君大安，董真命神。"]},{"t":"内经真谚","f":"古风","c":["子欲夜书。","当修常居。"]},{"t":"太平酒谚","f":"古风","c":["欲得长生。","饮太平。"]},{"t":"南土人为牡蛎语","f":"古风","c":["得合涧一蛎，虽不足豪，亦可以高。"]},{"t":"西晋永嘉五年墓砖铭","f":"古风","c":["子孙昌，皆侯王。"]},{"t":"东晋泰宁三年墓砖铭","f":"古风","c":["吉且阳，宜侯王。"]},{"t":"西晋永嘉五年墓砖铭","f":"古风","c":["永嘉世，九州空。","余吴土，盛且丰。"]},{"t":"西晋永嘉间墓砖铭","f":"古风","c":["永嘉中，天下灾。","但江南，皆康平。"]},{"t":"西晋永嘉砖铭","f":"古风","c":["子孙千亿，皆寿万年。"]},{"t":"西晋永嘉砖铭","f":"古风","c":["永嘉世，九州礼。"]},{"t":"西晋永嘉砖铭","f":"古风","c":["永嘉世，九州荒。","余广州，平且康。"]},{"t":"西晋永嘉六年砖铭","f":"古风","c":["宜公侯，寿百年。"]},{"t":"西晋建兴三年墓砖铭","f":"古风","c":["永嘉世，天下荒。","余广州，皆平康。"]},{"t":"飓风谚","f":"古风","c":["朝三暮七，昼不过一。"]},{"t":"泡鱼蒿猪谚","f":"古风","c":["朝为泡鱼，暮为蒿猪。","朝为懒妇，暮为奔鱼孚。"]},{"t":"崔寔引农语","f":"古风","c":["二月昏，参星夕。","杏花盛，桑椹赤。","河射角，堪夜作。","犁星没，水生骨。"]},{"t":"李陵录别诗二十一首 其十五","f":"五言绝句","c":["红尘蔽天地，白日何冥冥。","许由不洗耳。","后世有何徵。"]},{"t":"古诗 其六","f":"五言古诗","c":["屡见流芳歇。","石门通越井。"]},{"t":"古诗","f":"古风","c":["啼呼哭泣，如吹胡笳。","有客从南来，赠我一抱笔。","离家千里客，戚戚多思复。","日暮途且远，游子悲故乡。"]},{"t":"武帝太康后童谣三首","f":"古风","c":["局缩肉。","数横目。","中国当败吴当复。","宫门柱。","且莫朽。","吴当复在三十年后。"]},{"t":"元康三的蜀中童谣四首","f":"古风","c":["郫城坚。","盎底穿。","郫城细子李持细。","江桥头。","阙下市。","城都北门十八子。","有客有客。","来侵门陌。","其气欲索。"]}]};